{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-0MzUlm/src/parse.js","content":"import { ElectionError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/**
 * Parse an election from raw standard input text into a candidate list
 * (in declaration order) and a list of ballots. Throws ElectionError on
 * any malformed or invalid line, and a plain Error with no `line` for an
 * input that never declares candidates.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null || ballots.length > 0) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new ElectionError('expected candidates <name>...', lineNumber)
      }
      const names = tokens.slice(1)
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ElectionError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new ElectionError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
      }
      candidates = names
      continue
    }

    if (directive === 'ballot') {
      if (candidates === null) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new ElectionError('expected ballot <count> <candidate>...', lineNumber)
      }
      const countText = tokens[1]
      if (!COUNT_PATTERN.test(countText)) {
        throw new ElectionError('count must be a positive integer', lineNumber)
      }
      const count = Number(countText)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ElectionError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
      continue
    }

    throw new ElectionError(`unknown directive ${directive}`, lineNumber)
  }

  if (candidates === null) {
    throw new Error('no candidates')
  }

  return { candidates, ballots }
}
"}

