 * Parses a limiter file into declared policies, routes and events, or
 * throws a `ParseError` naming the offending line.
 */

const NAME_CHARS = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function fail(line, reason) {
  throw new ParseError(line, reason)
}

function parseCount(str, line, field, least) {
  if (!INT_RE.test(str)) fail(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(str)
  if (value < BigInt(least)) fail(line, `${field} must be an integer of at least ${least}`)
  return value
}

export function parseProgram(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue

    const tokens = raw.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 5) fail(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityStr, refillStr, perStr] = tokens
      if (!NAME_CHARS.test(name)) fail(lineNo, `invalid policy name ${name}`)
      const capacity = parseCount(capacityStr, lineNo, 'capacity', 1)
      const refill = parseCount(refillStr, lineNo, 'refill', 0)
