{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-70Vlxc/src/simulate.js","content":"/**
 * Runs a parsed program's events through its policies, producing the
 * per-event verdicts and per-key totals that the two CLI modes report.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

/** The route whose prefix is longest among those that match the key, or `null`. */
function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix) && (best === null || route.prefix.length > best.prefix.length)) {
      best = route
    }
  }
  return best
}

export function simulate(program) {
  const { policies, routes, events } = program

  const engines = new Map()
  for (const [name, def] of policies) {
    engines.set(name, def.type === 'bucket' ? new TokenBucket(def) : new SlidingWindow(def))
  }

  const replayLines = []
  const perKey = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  for (const ev of events) {
    const route = findRoute(routes, ev.key)
    let allow = true
    let denyPolicy = null

    if (route) {
      for (const pname of route.policyNames) engines.get(pname).advance(ev.key, ev.tick)
      for (const pname of route.policyNames) {
        if (!engines.get(pname).allow(ev.key)) {
          allow = false
          denyPolicy = pname
          break
        }
      }
      if (allow) {
        for (const pname of route.policyNames) engines.get(pname).record(ev.key, ev.tick)
      }
    }

    let counts = perKey.get(ev.key)
    if (!counts) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(ev.key, counts)
    }

    if (allow) {
      counts.allowed++
      totalAllowed++
      replayLines.push(`${ev.tick} ${ev.key} allow`)
    } else {
      counts.denied++
      totalDenied++
      replayLines.push(`${ev.tick} ${ev.key} deny ${denyPolicy}`)
    }
  }

  return { replayLines, perKey, totalAllowed, totalDenied }
}
"}

