{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-70Vlxc/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parseProgram, ParseError } from './parse.js'
import { simulate } from './simulate.js'

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

let input = ''
process.stdin.setEncoding('utf8')
for await (const chunk of process.stdin) input += chunk

try {
  const program = parseProgram(input)
  const { replayLines, perKey, totalAllowed, totalDenied } = simulate(program)

  let out = ''
  if (mode === 'replay') {
    for (const line of replayLines) out += line + '\n'
  } else {
    for (const key of [...perKey.keys()].sort()) {
      const counts = perKey.get(key)
      out += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  }

  process.stdout.write(out)
  process.exit(0)
} catch (err) {
  if (err instanceof ParseError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}
"}

