    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokensNum: this.cap, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.tokensNum += this.refill * elapsed
      if (state.tokensNum > this.cap) state.tokensNum = this.cap
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.states.get(key)
    return state.tokensNum >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.tokensNum -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.ticks.length && state.ticks[cut] <= threshold) cut += 1
    if (cut > 0) state.ticks = state.ticks.slice(cut)
  }

  allow(key) {
    const state = this.states.get(key)
    return BigInt(state.ticks.length) < this.limit
  }

  record(key, tick) {
    const state = this.states.get(key)
    state.ticks.push(tick)
  }
