{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { LexError, scan } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
  usageError()
}

const input = readFileSync(0, 'utf8')

let tokens
try {
  tokens = scan(input)
} catch (err) {
  if (err instanceof LexError) {
    process.stderr.write(`error: ${err.pos.line}:${err.pos.col}: ${err.message}\n`)
    process.exit(2)
  }
  throw err
}

if (mode === 'tokens') {
  let out = ''
  for (const token of tokens) {
    out += `${token.pos.line}:${token.pos.col} ${token.kind} ${token.text}\n`
  }
  process.stdout.write(out)
} else {
  const counts = Object.fromEntries(STAT_KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) counts[token.kind]++
  let out = ''
  for (const kind of STAT_KINDS) out += `${kind} ${counts[kind]}\n`
  out += `total ${tokens.length}\n`
  process.stdout.write(out)
}
"}

