const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^\d+$/

function lineError(lineNumber, message) {
  return new CliError(2, `line ${lineNumber}: ${message}`)
}

function checkName(name, lineNumber) {
  if (!NAME_PATTERN.test(name)) {
    throw lineError(lineNumber, `invalid task name ${name}`)
  }
}

/**
 * Parses a build graph from raw text into a task cost map and a dependency
 * map (task name -> set of names it depends on). Throws a `CliError` for any
 * malformed line, a duplicate task, or a `dep` line naming an undeclared
 * task.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const costs = new Map()
  const deps = new Map()
  const usages = []

  const ensureDeps = (name) => {
    if (!deps.has(name)) deps.set(name, new Set())
  }

  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw lineError(lineNumber, 'expected task <name> <cost>')
      }
      const [, name, costText] = words
      checkName(name, lineNumber)
      if (!COST_PATTERN.test(costText)) {
        throw lineError(lineNumber, 'cost must be a non-negative integer')
      }
      if (costs.has(name)) {
        throw lineError(lineNumber, `task ${name} is declared twice`)
      }
      costs.set(name, parseInt(costText, 10))
      ensureDeps(name)
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw lineError(lineNumber, 'expected dep <name> <dependency>...')
      }
      const name = words[1]
      checkName(name, lineNumber)
      ensureDeps(name)
      usages.push(name)
      const targets = deps.get(name)
      for (let i = 2; i < words.length; i++) {
        const dependency = words[i]
        checkName(dependency, lineNumber)
        usages.push(dependency)
        targets.add(dependency)
      }
    } else {
      throw lineError(lineNumber, `unknown directive ${directive}`)
    }
  }

  for (const name of usages) {
    if (!costs.has(name)) {
      throw new CliError(2, `unknown task ${name}`)
    }
  }

  return { costs, deps }
}
