{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-FUZhwc/src/lexer.js","content":"/**
 * The scanner. `scan(input)` turns UTF-8 source text into a list of tokens,
 * each `{ kind, line, col, text, value }`, where `value` is only set for
 * `string` and `rawstring` tokens (their decoded contents) and `text` holds
 * the source text for every other kind. Positions count from 1; a tab moves
 * the column forward to the next multiple of 4 plus 1, a line feed moves to
 * the next line, and every other code point moves the column forward by
 * one. On a scan error it throws a `LexError` carrying the offending
 * `line`, `col` and `message`.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isDecimalDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBinaryDigit = (c) => c === '0' || c === '1'
const isOctalDigit = (c) => c !== undefined && c >= '0' && c <= '7'
const isIdentStart = (c) => c !== undefined && /^[A-Za-z_]$/.test(c)
const isIdentPart = (c) => c !== undefined && /^[A-Za-z0-9_]$/.test(c)

export class LexError extends Error {
  constructor(line, col, message) {
    super(message)
    this.line = line
    this.col = col
  }
}

export function scan(input) {
  const chars = Array.from(input)
  let idx = 0
  let line = 1
  let col = 1

  const atEnd = () => idx >= chars.length
  const peek = (offset = 0) => chars[idx + offset]
  const posNow = () => ({ line, col })
  const fail = (pos, message) => {
    throw new LexError(pos.line, pos.col, message)
  }
  const consume = () => {
    const c = chars[idx]
    idx++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  function skipWhitespaceAndComments() {
    for (;;) {
      const c = peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        consume()
        continue
      }
      if (c === '/' && peek(1) === '/') {
        while (!atEnd() && peek() !== '\n') consume()
        continue
      }
      if (c === '/' && peek(1) === '*') {
        const openPos = posNow()
        consume()
        consume()
        let depth = 1
        while (depth > 0) {
          if (atEnd()) fail(openPos, 'unterminated block comment')
          if (peek() === '/' && peek(1) === '*') {
            consume()
            consume()
            depth++
            continue
          }
          if (peek() === '*' && peek(1) === '/') {
