{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { parseElection, ParseError } from './parse.js'
import { runElection } from './election.js'
import { formatRound, formatOutcome } from './format.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readInput()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      fail(err.line === undefined ? err.message : `line ${err.line}: ${err.message}`)
    }
    throw err
  }

  const { rounds, winner } = runElection(election)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      lines.push(formatRound(round, index + 1))
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(formatOutcome(winner))

  process.stdout.write(lines.join('\n') + '\n')
}

function readInput() {
  const { readFileSync } = require('node:fs')
  return readFileSync(0, 'utf8')
}

main()
"}

