{"file_path":"src/render.js","content":"/**
 * Rendering of a parsed document tree, either as canonical JSON or as the
 * flat "keys" listing.
 */

function compareByCodePoint(a, b) {
  const ai = Array.from(a)
  const bi = Array.from(b)
  const len = Math.min(ai.length, bi.length)
  for (let i = 0; i < len; i++) {
    const ca = ai[i].codePointAt(0)
    const cb = bi[i].codePointAt(0)
    if (ca !== cb) return ca - cb
  }
  return ai.length - bi.length
}

function sortedKeys(entries) {
  return [...entries.keys()].sort(compareByCodePoint)
}

function toPlain(node) {
  switch (node.kind) {
    case 'table': {
      const obj = {}
      for (const key of sortedKeys(node.entries)) {
        obj[key] = toPlain(node.entries.get(key))
      }
      return obj
    }
    case 'array-of-tables':
    case 'array':
      return node.items.map(toPlain)
    default:
      return node.value
  }
}

export function toJson(root) {
  return `${JSON.stringify(toPlain(root), null, 2)}\n`
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array-of-tables':
    case 'array':
      return 'array'
    default:
      return node.kind
  }
}

function walk(node, path, lines) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node.entries)) {
      const child = node.entries.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      lines.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, lines)
    }
  } else if (node.kind === 'array-of-tables' || node.kind === 'array') {
    node.items.forEach((child, idx) => {
      const childPath = `${path}[${idx}]`
      lines.push(`${childPath} ${typeName(child)}`)
      walk(child, childPath, lines)
    })
  }
}

export function toKeys(root) {
  const lines = []
  walk(root, '', lines)
  return lines.length === 0 ? '' : `${lines.join('\n')}\n`
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { parseDocument, ParseError } from './parser.js'
import { toJson, toKeys } from './render.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const mode = args[0]
  const input = readStdin()

  let root
  try {
    root = parseDocument(input)
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(`error: line ${err.line}: ${err.reason}\n`)
      process.exit(2)
    }
    throw err
  }

  process.stdout.write(mode === 'json' ? toJson(root) : toKeys(root))
  process.exit(0)
}

main()
"}

