{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3dZDI/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, built on the token stream
 * from lexer.js.
 *
 * Precedence, loosest first: comparisons, then `+`/`-`, then `*`/`/`, then
 * `^`, then a leading unary `-`/`+`. The comparison and additive/
 * multiplicative levels are left-associative; `^` is right-associative and
 * a leading sign binds tighter than `^`, so the base of `^` reparses through
 * Unary on each side.
 *
 * A range (`A1:B3`) parses as a Primary anywhere an address would, so it can
 * appear nested in any expression; only the evaluator restricts a range to
 * function-argument position (see evaluate.js).
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseError extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new ParseError('expected ' + type)
    return this.next()
  }

  parseExpr() {
    let left = this.parseAdditive()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && COMPARISON_OPS.has(t.value)) {
        this.next()
        const right = this.parseAdditive()
        left = { type: 'bin', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && (t.value === '+' || t.value === '-')) {
        this.next()
        const right = this.parseMultiplicative()
        left = { type: 'bin', op: t.value, left, right }
      } else break
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    for (;;) {
      const t = this.peek()
      if (t && t.type === 'OP' && (t.value === '*' || t.value === '/')) {
        this.next()
        const right = this.parsePower()
        left = { type: 'bin', op: t.value, left, right }
      } else break
    }
    return left
  }

  // Power -> Unary ('^' Power)?, right-associative, with Unary allowed to
  // reintroduce a leading sign on either side.
  parsePower() {
    const base = this.parseUnary()
    const t = this.peek()
    if (t && t.type === 'OP' && t.value === '^') {
      this.next()
      const exponent = this.parsePower()
      return { type: 'bin', op: '^', left: base, right: exponent }
    }
    return base
  }

  parseUnary() {
    const t = this.peek()
    if (t && t.type === 'OP' && (t.value === '-' || t.value === '+')) {
      this.next()
      const expr = this.parseUnary()
      return { type: 'unary', op: t.value, expr }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of input')

    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'num', value: Number(t.value) }
    }

    if (t.type === 'LPAREN') {
      this.next()
      const expr = this.parseExpr()
      this.expect('RPAREN')
      return expr
    }

    if (t.type === 'IDENT') {
      // A range: IDENT ':' IDENT, valid as a Primary anywhere.
      const after = this.peek(1)
      if (after && after.type === 'COLON') {
        const from = this.next().value
        this.next() // COLON
        const toTok = this.peek()
        if (!toTok || toTok.type !== 'IDENT') throw new ParseError('expected address after :')
        this.next()
        return { type: 'range', from, to: toTok.value }
      }

      const nameTok = this.next()
      const name = nameTok.value

      if (this.peek() && this.peek().type === 'LPAREN') {
        this.next()
        const args = []
        if (!(this.peek() && this.peek().type === 'RPAREN')) {
          args.push(this.parseArgument())
          while (this.peek() && this.peek().type === 'COMMA') {
            this.next()
            args.push(this.parseArgument())
          }
        }
        this.expect('RPAREN')
        return { type: 'call', name: name.toUpperCase(), args }
      }

      const upper = name.toUpperCase()
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'address', text: upper }
    }

    throw new ParseError('unexpected token')
  }

  // A function argument is a range written directly (A1:B3) or any
