export function compareAddresses(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

/** Builds canonical address text (e.g. "AA12") from a column/row pair. */
export function formatAddress(col, row) {
  let c = col
  let letters = ''
  while (c > 0) {
    const rem = (c - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    c = Math.floor((c - 1) / 26)
  }
  return letters + String(row)
}

/**
 * Returns the addresses covered by the rectangle between two corners, in
 * ascending column then ascending row order, or null when either corner
 * text is not a valid in-range address.
 */
export function rangeCells(fromText, toText) {
  const from = parseAddress(fromText)
  const to = parseAddress(toText)
  if (!from || !to) return null
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    for (let r = rowMin; r <= rowMax; r++) cells.push(formatAddress(c, r))
  }
  return cells
}"}

