 * Renders a value the way `values` mode prints it.
 */

/** Rounds to ten significant digits, then prints the way JavaScript would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}

export function formatValue(value) {
  switch (value.type) {
    case 'number':
      return formatNumber(value.value)
    case 'error':
      return value.value
    case 'boolean':
      return value.value ? 'TRUE' : 'FALSE'
    case 'text':
      return value.value
    default:
      throw new Error('unreachable value kind')
  }
}
"}

