    return Number.isFinite(result) ? mkNumber(result) : ERR_DIV0
  }

  evalCall(node) {
    const arity = AGGREGATE_ARITY[node.name]
    if (!arity) return ERR_NAME
    if (node.args.length < arity.min || node.args.length > arity.max) return ERR_ERR

    if (node.name === 'IF') return this.evalIf(node)

    const flat = this.flattenArgs(node.args)

    if (node.name === 'COUNT') {
      for (const v of flat) if (v.type === 'error') return v
      return mkNumber(flat.filter((v) => v.type === 'number').length)
    }

    const nums = []
    for (const v of flat) {
      const n = asNumber(v)
      if (typeof n !== 'number') return n
      nums.push(n)
    }

    switch (node.name) {
      case 'SUM': {
        const sum = nums.reduce((a, b) => a + b, 0)
        return Number.isFinite(sum) ? mkNumber(sum) : ERR_DIV0
      }
      case 'MIN':
        return mkNumber(Math.min(...nums))
      case 'MAX':
        return mkNumber(Math.max(...nums))
      case 'AVG': {
        const avg = nums.reduce((a, b) => a + b, 0) / nums.length
        return Number.isFinite(avg) ? mkNumber(avg) : ERR_DIV0
      }
      case 'ABS': {
        const abs = Math.abs(nums[0])
        return Number.isFinite(abs) ? mkNumber(abs) : ERR_DIV0
      }
      default:
        throw new Error('unreachable function name')
    }
  }

  evalIf(node) {
    const cond = this.evalNode(node.args[0])
    if (cond.type === 'error') return cond
    let truthy
    if (cond.type === 'boolean') truthy = cond.value
    else if (cond.type === 'number') truthy = cond.value !== 0
    else return ERR_VALUE
    return this.evalNode(node.args[truthy ? 1 : 2])
  }

  // Flattens call arguments left to right into a value list, expanding any
  // argument that is directly a range into the values of every cell it
  // covers, in ascending column then ascending row order.
  flattenArgs(argNodes) {
    const flat = []
    for (const arg of argNodes) {
      if (arg.type === 'range') {
        const cells = rangeCells(arg.from, arg.to)
        if (!cells) {
          flat.push(ERR_REF)
        } else {
          for (const addr of cells) flat.push(this.getValue(addr))
        }
      } else {
        flat.push(this.evalNode(arg))
      }
    }
    return flat
