{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-M3pJJB/src/parser.js","content":"/**
 * The parser: turns the text of a configuration document into the node tree
 * defined in nodes.js, or throws a ParseError.
 */

import { err } from './errors.js'
import { readBasicStringRaw, readLiteralStringRaw } from './strings.js'
import { tableNode, arrayNode, stringNode, integerNode, floatNode, booleanNode, pushKey, pushIndex } from './nodes.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const INTEGER_RE = /^[+-]?[0-9]+(?:_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(?:_[0-9]+)*(?:(?:\.[0-9]+(?:_[0-9]+)*)(?:[eE][+-]?[0-9]+(?:_[0-9]+)*)?|(?:[eE][+-]?[0-9]+(?:_[0-9]+)*))$/

function skipWs(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos += 1
  return pos
}

// Skips whitespace, then reports whether the line has effectively ended:
// either the text ran out or an unquoted comment marker starts here.
function atEnd(line, pos) {
  const p = skipWs(line, pos)
  if (p >= line.length) return { end: true, pos: p }
  if (line[p] === '#' || line[p] === ';') return { end: true, pos: p }
  return { end: false, pos: p }
}

function isBlankOrComment(line) {
  const p = skipWs(line, 0)
  return p >= line.length || line[p] === '#' || line[p] === ';'
}

function parseName(line, pos, lineNo) {
  const ch = line[pos]
  if (ch === '"') return readBasicStringRaw(line, pos, lineNo)
  if (ch === "'") return readLiteralStringRaw(line, pos, lineNo)
  const start = pos
  while (pos < line.length && NAME_CHAR.test(line[pos])) pos += 1
  if (pos === start) throw err(lineNo, 'expected a name')
  return { value: line.slice(start, pos), pos }
}

function parseDottedName(line, pos, lineNo) {
  pos = skipWs(line, pos)
  const first = parseName(line, pos, lineNo)
  const names = [first.value]
  pos = first.pos
  while (true) {
    const save = pos
    const afterWs = skipWs(line, pos)
    if (line[afterWs] === '.') {
      pos = skipWs(line, afterWs + 1)
      const next = parseName(line, pos, lineNo)
      names.push(next.value)
      pos = next.pos
    } else {
      pos = save
      break
    }
  }
  return { names, pos }
}

// Walks one intermediate component of a dotted path, creating an implicit
// table when the name is unused, and following the last element when the
// name holds an array of tables.
function descend(table, name, path, lineNo) {
  const newPath = pushKey(path, name)
  const node = table.entries.get(name)
  if (node === undefined) {
    const t = tableNode()
    table.entries.set(name, t)
    return { table: t, path: newPath }
  }
  if (node.kind === 'table') return { table: node, path: newPath }
  if (node.kind === 'array' && node.isAOT) {
    const idx = node.items.length - 1
    return { table: node.items[idx], path: pushIndex(newPath, idx) }
  }
  throw err(lineNo, `${newPath} is not a table`)
}

function parseBareValue(line, pos, lineNo) {
  const start = pos
  while (pos < line.length && !' \t,]}'.includes(line[pos])) pos += 1
  const token = line.slice(start, pos)
  if (token === 'true') return { node: booleanNode(true), pos }
  if (token === 'false') return { node: booleanNode(false), pos }
  if (INTEGER_RE.test(token)) return { node: integerNode(parseIntegerToken(token)), pos }
  if (FLOAT_RE.test(token)) return { node: floatNode(Number(token.replace(/_/g, ''))), pos }
  throw err(lineNo, `invalid value ${token}`)
}

function parseIntegerToken(token) {
  const negative = token[0] === '-'
  const digits = token.replace(/^[+-]/, '').replace(/_/g, '')
  const magnitude = BigInt(digits)
  return negative ? -magnitude : magnitude
}

function parseValueRequired(line, pos, lineNo, path) {
  const r = atEnd(line, pos)
  if (r.end) throw err(lineNo, 'expected a value')
  pos = r.pos
  const ch = line[pos]
  if (ch === ',' || ch === ']' || ch === '}') throw err(lineNo, 'expected a value')
  if (ch === '"') {
    const s = readBasicStringRaw(line, pos, lineNo)
    return { node: stringNode(s.value), pos: s.pos }
  }
  if (ch === "'") {
    const s = readLiteralStringRaw(line, pos, lineNo)
    return { node: stringNode(s.value), pos: s.pos }
  }
  if (ch === '[') return parseArray(line, pos, lineNo, path)
  if (ch === '{') return parseInlineTable(line, pos, lineNo, path)
  return parseBareValue(line, pos, lineNo)
}

function parseArray(line, pos, lineNo, path) {
  pos += 1 // consume '['
  const items = []
  let r = atEnd(line, pos)
  if (r.end) throw err(lineNo, 'unterminated array')
  pos = r.pos
  if (line[pos] === ']') return { node: arrayNode(items, false), pos: pos + 1 }
  while (true) {
    const elementPath = pushIndex(path, items.length)
    const v = parseValueRequired(line, pos, lineNo, elementPath)
    items.push(v.node)
    pos = v.pos
    r = atEnd(line, pos)
    if (r.end) throw err(lineNo, 'unterminated array')
    pos = r.pos
    if (line[pos] === ',') {
      pos += 1
      r = atEnd(line, pos)
      if (r.end) throw err(lineNo, 'unterminated array')
      pos = r.pos
      if (line[pos] === ']') return { node: arrayNode(items, false), pos: pos + 1 }
      continue
    }
    if (line[pos] === ']') return { node: arrayNode(items, false), pos: pos + 1 }
    throw err(lineNo, 'unterminated array')
  }
}

function parseInlineTable(line, pos, lineNo, path) {
  pos += 1 // consume '{'
  const table = tableNode()
  table.headerLocked = true
  let r = atEnd(line, pos)
  if (r.end) throw err(lineNo, 'unterminated inline table')
  pos = r.pos
  if (line[pos] === '}') return { node: table, pos: pos + 1 }
  while (true) {
    const res = parseAssignment(line, pos, lineNo, table, path, 'inline')
    pos = res.pos
    r = atEnd(line, pos)
    if (r.end) throw err(lineNo, 'unterminated inline table')
    pos = r.pos
    if (line[pos] === ',') {
      pos += 1
      r = atEnd(line, pos)
      if (r.end) throw err(lineNo, 'unterminated inline table')
      pos = r.pos
      if (line[pos] === '}') throw err(lineNo, 'expected a name')
      continue
    }
    if (line[pos] === '}') return { node: table, pos: pos + 1 }
    throw err(lineNo, 'unterminated inline table')
  }
}

// Parses `<dotted name> = <value>` starting at pos, and assigns the value
// into targetTable (whose path from the root is basePath). Used both for
// top-level lines and for entries inside an inline table.
function parseAssignment(line, pos, lineNo, targetTable, basePath, errCtx) {
  const { names, pos: p1 } = parseDottedName(line, pos, lineNo)
  let pos2 = skipWs(line, p1)
  if (line[pos2] !== '=') {
    throw err(lineNo, errCtx === 'inline' ? 'expected = in an inline table' : 'expected key = value')
  }
  pos2 += 1
  const prospectivePath = names.reduce((p, n) => pushKey(p, n), basePath)
  const { node: valueNode, pos: p2 } = parseValueRequired(line, pos2, lineNo, prospectivePath)

  let table = targetTable
  let path = basePath
  for (let i = 0; i < names.length - 1; i += 1) {
    ;({ table, path } = descend(table, names[i], path, lineNo))
  }
  const last = names[names.length - 1]
  const finalPath = pushKey(path, last)
  if (table.entries.has(last)) throw err(lineNo, `key ${finalPath} is defined twice`)
  table.entries.set(last, valueNode)
  return { pos: p2 }
}

function parseHeader(line, pos, lineNo, ctx, root) {
  let isArray = false
  pos += 1 // consume first '['
  if (line[pos] === '[') {
    isArray = true
    pos += 1
  }
  pos = skipWs(line, pos)
  const { names, pos: p1 } = parseDottedName(line, pos, lineNo)
  pos = skipWs(line, p1)
  if (line[pos] !== ']') throw err(lineNo, 'unterminated table header')
  pos += 1
  if (isArray) {
    if (line[pos] !== ']') throw err(lineNo, 'unterminated table header')
    pos += 1
  }
  const t = atEnd(line, pos)
  if (!t.end) throw err(lineNo, 'trailing text after a table header')

  let table = root
  let path = ''
  for (let i = 0; i < names.length - 1; i += 1) {
    ;({ table, path } = descend(table, names[i], path, lineNo))
  }
  const last = names[names.length - 1]
  const finalPath = pushKey(path, last)

  if (!isArray) {
    const node = table.entries.get(last)
    if (node === undefined) {
      const t2 = tableNode()
      t2.headerLocked = true
      table.entries.set(last, t2)
      ctx.currentTable = t2
      ctx.currentTablePath = finalPath
    } else if (node.kind === 'table') {
      if (node.headerLocked) throw err(lineNo, `table ${finalPath} is defined twice`)
      node.headerLocked = true
      ctx.currentTable = node
      ctx.currentTablePath = finalPath
    } else {
      throw err(lineNo, `${finalPath} is not a table`)
    }
    return
  }

  let node = table.entries.get(last)
  if (node === undefined) {
    node = arrayNode([], true)
    table.entries.set(last, node)
  } else if (!(node.kind === 'array' && node.isAOT)) {
    throw err(lineNo, `${finalPath} is not an array of tables`)
  }
  const t2 = tableNode()
  node.items.push(t2)
  ctx.currentTable = t2
  ctx.currentTablePath = pushIndex(finalPath, node.items.length - 1)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = tableNode()
  root.headerLocked = true
  const ctx = { currentTable: root, currentTablePath: '' }

  for (let i = 0; i < lines.length; i += 1) {
