  const r = atEnd(line, pos)
  if (r.end) throw err(lineNo, 'expected a value')
  pos = r.pos
  const ch = line[pos]
  if (ch === ',' || ch === ']' || ch === '}') throw err(lineNo, 'expected a value')
  if (ch === '"') {
    const s = readBasicStringRaw(line, pos, lineNo)
    return { node: stringNode(s.value), pos: s.pos }
  }
  if (ch === "'") {
    const s = readLiteralStringRaw(line, pos, lineNo)
    return { node: stringNode(s.value), pos: s.pos }
  }
  if (ch === '[') return parseArray(line, pos, lineNo, path)
  if (ch === '{') return parseInlineTable(line, pos, lineNo, path)
  return parseBareValue(line, pos, lineNo)
}

