    const elementPath = pushIndex(path, items.length)
    const v = parseValueRequired(line, pos, lineNo, elementPath)
    items.push(v.node)
    pos = v.pos
    r = atEnd(line, pos)
    if (r.end) throw err(lineNo, 'unterminated array')
