{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-Q1GORX/src/parser.js","content":"import { ParseError } from './errors.js'
import { LineScanner } from './line-scanner.js'
import { makeTable } from './nodes.js'
import { assignInto, resolveHeader } from './assign.js'
import { parseValue } from './value-parser.js'

function firstMeaningfulChar(line) {
  for (let i = 0; i < line.length; i++) {
    const c = line[i]
    if (c !== ' ' && c !== '\t') return c
  }
  return undefined
}

function parseHeaderLine(scanner) {
  scanner.pos++ // '['
  let isArray = false
  if (scanner.peek() === '[') {
    isArray = true
    scanner.pos++
  }
  scanner.skipWs()
  const names = scanner.parseNameList()
  scanner.skipWs()
  if (scanner.peek() !== ']') scanner.fail('unterminated table header')
  scanner.pos++
  if (isArray) {
    if (scanner.peek() !== ']') scanner.fail('unterminated table header')
    scanner.pos++
  }
  scanner.requireLineEnd('trailing text after a table header')
  return { names, isArray }
}

function parseKeyValueLine(scanner, currentTable, currentPath) {
  const names = scanner.parseNameList()
  scanner.skipWs()
  if (scanner.peek() !== '=') scanner.fail('expected key = value')
  scanner.pos++
  scanner.skipWs()
  const value = parseValue(scanner, [...currentPath, ...names])
  assignInto(currentTable, names, value, scanner.lineNo, currentPath)
  scanner.requireLineEnd('trailing text after a value')
}

/**
 * Parses a whole configuration document, returning its root table. Throws a
 * `ParseError` at the first line that fails.
 */
export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = makeTable()
  root.headerOpened = true
  let currentTable = root
  let currentPath = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    const first = firstMeaningfulChar(line)
    if (first === undefined || first === '#' || first === ';') continue

    const scanner = new LineScanner(line, lineNo)
    scanner.skipWs()
    if (scanner.peek() === '[') {
      const { names, isArray } = parseHeaderLine(scanner)
      currentTable = resolveHeader(root, names, isArray, lineNo)
      currentPath = names
    } else {
      parseKeyValueLine(scanner, currentTable, currentPath)
    }
  }

  return root
}

export { ParseError }
"}

