{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-WTpTRD/src/parser.js","content":"/**
 * Builds the document tree from configuration text: table headers, array of
 * tables headers, and dotted-key assignments, each contributing nodes to a
 * tree of tables, arrays, and scalars.
 */

import { Cursor, ParseError, parseDottedName, parseString, classifyBareToken } from './lexer.js'

export { ParseError }

function makeTable() {
  return { kind: 'table', entries: new Map(), headerDefined: false }
}

export function formatPath(path) {
  let out = ''
  for (const seg of path) {
    if (typeof seg === 'string') out += (out.length ? '.' : '') + seg
    else out += `[${seg.idx}]`
  }
  return out
}

/**
 * Walks `names` under `table` (whose own path is `tablePath`), creating an
 * implicit table for each missing step and descending into the last element
 * when a step already holds an array of tables. Returns the table reached
 * and its path.
 */
function walkIntermediate(table, tablePath, names, cur) {
  let node = table
  let path = tablePath
  for (const key of names) {
    path = path.concat([key])
    let entry = node.entries.get(key)
    if (!entry) {
      entry = makeTable()
      node.entries.set(key, entry)
    } else if (entry.kind === 'table') {
      // descend
    } else if (entry.kind === 'arraytable') {
      entry = entry.value[entry.value.length - 1]
    } else {
      cur.fail(`${formatPath(path)} is not a table`)
    }
    node = entry
  }
  return { node, path }
}

/**
 * Resolves where `names` assigns under `table`/`tablePath`, failing if the
 * leaf is already defined. Returns the parent table, the leaf key, and the
 * leaf's full path, leaving the caller to set the value once it is parsed.
 */
function assignInto(table, tablePath, names, cur) {
  const { node: parent, path: parentPath } = walkIntermediate(table, tablePath, names.slice(0, -1), cur)
  const leaf = names[names.length - 1]
  const leafPath = parentPath.concat([leaf])
  if (parent.entries.has(leaf)) cur.fail(`key ${formatPath(leafPath)} is defined twice`)
  return { parent, leaf, leafPath }
}

function parseValue(cur, path) {
  cur.skipWs()
  if (cur.i >= cur.s.length) cur.fail('expected a value')
  const c = cur.s[cur.i]
  if (c === ',' || c === ']' || c === '}') cur.fail('expected a value')
  if (c === '"' || c === "'") return { kind: 'string', value: parseString(cur) }
  if (c === '[') return parseArray(cur, path)
  if (c === '{') return parseInlineTable(cur, path)
  const start = cur.i
  while (cur.i < cur.s.length && !' \t,]}'.includes(cur.s[cur.i])) cur.i++
  const token = cur.s.slice(start, cur.i)
  return classifyBareToken(token, cur)
}

function parseArray(cur, path) {
  cur.i++
  const items = []
  let idx = 0
  while (true) {
    cur.skipWs()
    if (cur.i >= cur.s.length) cur.fail('unterminated array')
    if (cur.s[cur.i] === ']') { cur.i++; break }
    items.push(parseValue(cur, path.concat([{ idx }])))
    idx++
    cur.skipWs()
    if (cur.i >= cur.s.length) cur.fail('unterminated array')
    if (cur.s[cur.i] === ',') { cur.i++; continue }
    if (cur.s[cur.i] === ']') { cur.i++; break }
    cur.fail('trailing text after a value')
  }
  return { kind: 'array', value: items }
}

function parseInlineTable(cur, path) {
  cur.i++
  const table = makeTable()
  cur.skipWs()
  if (cur.i < cur.s.length && cur.s[cur.i] === '}') { cur.i++; return table }
  if (cur.i >= cur.s.length) cur.fail('unterminated inline table')
  while (true) {
    const names = parseDottedName(cur)
    cur.skipWs()
    if (cur.i >= cur.s.length || cur.s[cur.i] !== '=') cur.fail('expected = in an inline table')
    cur.i++
    const { parent, leaf, leafPath } = assignInto(table, path, names, cur)
    parent.entries.set(leaf, parseValue(cur, leafPath))
    cur.skipWs()
    if (cur.i >= cur.s.length) cur.fail('unterminated inline table')
    if (cur.s[cur.i] === ',') {
      cur.i++
      cur.skipWs()
      if (cur.i >= cur.s.length) cur.fail('unterminated inline table')
      continue
    }
    if (cur.s[cur.i] === '}') { cur.i++; break }
    cur.fail('trailing text after a value')
  }
  return table
}

function processHeader(doc, names, arrayHeader, cur) {
  const { node: parent, path: parentPath } = walkIntermediate(doc.root, [], names.slice(0, -1), cur)
  const leaf = names[names.length - 1]
  const leafPath = parentPath.concat([leaf])
  let entry = parent.entries.get(leaf)
  if (arrayHeader) {
    if (!entry) {
      entry = { kind: 'arraytable', value: [] }
      parent.entries.set(leaf, entry)
    } else if (entry.kind !== 'arraytable') {
      cur.fail(`${formatPath(leafPath)} is not an array of tables`)
    }
    const fresh = makeTable()
    entry.value.push(fresh)
    doc.current = fresh
    doc.currentPath = leafPath.concat([{ idx: entry.value.length - 1 }])
  } else {
    if (!entry) {
      entry = makeTable()
      entry.headerDefined = true
      parent.entries.set(leaf, entry)
    } else if (entry.kind === 'table') {
      if (entry.headerDefined) cur.fail(`table ${formatPath(leafPath)} is defined twice`)
      entry.headerDefined = true
    } else {
      cur.fail(`${formatPath(leafPath)} is not a table`)
    }
    doc.current = entry
    doc.currentPath = leafPath
  }
}

function parseHeaderLine(doc, cur) {
  let arrayHeader = false
  cur.i++
  if (cur.s[cur.i] === '[') { arrayHeader = true; cur.i++ }
  const names = parseDottedName(cur)
  cur.skipWs()
  if (cur.i >= cur.s.length || cur.s[cur.i] !== ']') cur.fail('unterminated table header')
  cur.i++
  if (arrayHeader) {
    if (cur.i >= cur.s.length || cur.s[cur.i] !== ']') cur.fail('unterminated table header')
    cur.i++
  }
  cur.skipWs()
  if (cur.i < cur.s.length) cur.fail('trailing text after a table header')
  processHeader(doc, names, arrayHeader, cur)
}

function parseAssignmentLine(doc, cur) {
  const names = parseDottedName(cur)
  cur.skipWs()
  if (cur.i >= cur.s.length || cur.s[cur.i] !== '=') cur.fail('expected key = value')
  cur.i++
  const { parent, leaf, leafPath } = assignInto(doc.current, doc.currentPath, names, cur)
  const val = parseValue(cur, leafPath)
  cur.skipWs()
  if (cur.i < cur.s.length) cur.fail('trailing text after a value')
  parent.entries.set(leaf, val)
}

function firstSignificant(line) {
  const idx = line.search(/[^ \t]/)
  if (idx === -1) return -1
  const c = line[idx]
  if (c === '#' || c === ';') return -1
  return idx
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const doc = { root: makeTable(), current: null, currentPath: [] }
  doc.current = doc.root
  for (let ln = 0; ln < lines.length; ln++) {
    const line = lines[ln].endsWith('\r') ? lines[ln].slice(0, -1) : lines[ln]
    const lineNo = ln + 1
    const idx = firstSignificant(line)
    if (idx === -1) continue
    const cur = new Cursor(line, lineNo)
    cur.i = idx
    if (line[idx] === '[') parseHeaderLine(doc, cur)
    else parseAssignmentLine(doc, cur)
  }
  return doc.root
}
"}

