{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZRbWE3/src/parser.js","content":"import { LineError, SimpleError } from './errors.js'

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

/**
 * Parses the build graph text format into a map of task name to cost and a
 * map of task name to its declared dependency names (each depended-on name
 * listed once, in first-seen order). Throws {@link LineError} for malformed
 * directives and {@link SimpleError} for a dependency naming a task that no
 * `task` line declares.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map() // name -> cost
  const depDirectives = [] // { name, deps, line }, in file order

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new LineError(lineNo, 'expected task <name> <cost>')
      const [, name, costStr] = words
      if (!NAME_PATTERN.test(name)) throw new LineError(lineNo, `invalid task name ${name}`)
      if (!COST_PATTERN.test(costStr)) throw new LineError(lineNo, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw new LineError(lineNo, `task ${name} is declared twice`)
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) throw new LineError(lineNo, 'expected dep <name> <dependency>...')
      const [, name, ...deps] = words
      for (const n of [name, ...deps]) {
        if (!NAME_PATTERN.test(n)) throw new LineError(lineNo, `invalid task name ${n}`)
      }
      depDirectives.push({ name, deps })
    } else {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }
  }

  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, [])

  for (const directive of depDirectives) {
    for (const n of [directive.name, ...directive.deps]) {
      if (!tasks.has(n)) throw new SimpleError(`unknown task ${n}`)
    }
    const seen = new Set(deps.get(directive.name))
    for (const dep of directive.deps) {
      if (!seen.has(dep)) {
        seen.add(dep)
        deps.get(directive.name).push(dep)
      }
    }
  }

  return { tasks, deps }
}
"}

