{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZRbWE3/src/graph.js","content":"import { CycleError } from './errors.js'

/**
 * Finds a dependency cycle by depth-first search, starting from each task
 * in ascending name order and walking each task's dependencies in ascending
 * name order. Throws {@link CycleError} for the first cycle such a search
 * re-enters, with names running from the re-entered task through the search
 * stack back to itself. Returns nothing when the graph is acyclic.
 */
export function checkAcyclic(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function visit(name) {
    onStack.add(name)
    stack.push(name)
    for (const dep of [...deps.get(name)].sort()) {
      if (onStack.has(dep)) {
        const start = stack.indexOf(dep)
        throw new CycleError([...stack.slice(start), dep])
      }
      if (!visited.has(dep)) visit(dep)
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
  }

  for (const name of names) {
    if (!visited.has(name)) visit(name)
  }
}

/**
 * Computes, for every task, its start time (the greatest finish time among
 * its dependencies, or 0), its finish time (start plus cost), and its depth
 * (the greatest depth among its dependencies plus one, or 0). Assumes the
 * graph is acyclic.
 */
export function computeSchedule(tasks, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function compute(name) {
    if (finish.has(name)) return
    let maxFinish = 0
    let maxDepth = -1
    for (const dep of deps.get(name)) {
      compute(dep)
      if (finish.get(dep) > maxFinish) maxFinish = finish.get(dep)
      if (depth.get(dep) > maxDepth) maxDepth = depth.get(dep)
    }
    start.set(name, maxFinish)
