/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph } from './parser.js'
import { checkAcyclic, computeSchedule, packWorkers } from './graph.js'
import { LineError, SimpleError, CycleError } from './errors.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) fail('workers must be a positive integer')
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  fail(USAGE)
  return null
}

function formatWaves(tasks, schedule) {
  const { finish, depth } = schedule
  const byDepth = new Map()
  for (const name of tasks.keys()) {
    const d = depth.get(name)
    if (!byDepth.has(d)) byDepth.set(d, [])
    byDepth.get(d).push(name)
  }

  const lines = []
  const maxDepth = byDepth.size > 0 ? Math.max(...byDepth.keys()) : -1
  for (let k = 0; k <= maxDepth; k++) {
    const names = (byDepth.get(k) || []).sort()
    lines.push(`wave ${k}: ${names.join(' ')}`)
  }

  let total = 0
  for (const f of finish.values()) {
    if (f > total) total = f
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatExplain(tasks, schedule) {
  const { start, finish, depth } = schedule
  const names = [...tasks.keys()].sort()
  const lines = names.map((name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)

  let total = 0
  for (const f of finish.values()) {
    if (f > total) total = f
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function formatPack(workerRuns, makespan) {
  const lines = workerRuns.map((runs, i) => {
    const parts = runs.map((r) => ` ${r.name}@${r.start}-${r.finish}`)
    return `worker ${i}:${parts.join('')}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = readStdin()

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseGraph(input))
  } catch (err) {
    if (err instanceof LineError) fail(`line ${err.line}: ${err.message}`)
    if (err instanceof SimpleError) fail(err.message)
    throw err
  }

  try {
    checkAcyclic(tasks, deps)
  } catch (err) {
    if (err instanceof CycleError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(3)
    }
    throw err
  }

  if (args.mode === 'waves') {
    process.stdout.write(formatWaves(tasks, computeSchedule(tasks, deps)))
  } else if (args.mode === 'explain') {
    process.stdout.write(formatExplain(tasks, computeSchedule(tasks, deps)))
  } else {
    const { workerRuns, makespan } = packWorkers(tasks, deps, args.workers)
    process.stdout.write(formatPack(workerRuns, makespan))
  }
}

main()
"}

