const DIGIT = /[0-9]/
const LETTER = /[A-Za-z]/
const LETTER_OR_DIGIT = /[A-Za-z0-9]/
const SINGLE_PUNCT = '()^*/+-=<>,:'

export class LexError extends Error {}

export function tokenize(src) {
  const tokens = []
  let i = 0
  const n = src.length

  while (i < n) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }

    if (DIGIT.test(ch)) {
      let j = i + 1
      while (j < n && DIGIT.test(src[j])) j++
      if (src[j] === '.' && DIGIT.test(src[j + 1] || '')) {
        j++
        while (j < n && DIGIT.test(src[j])) j++
      }
      tokens.push({ type: 'number', value: src.slice(i, j) })
      i = j
      continue
    }

    if (LETTER.test(ch)) {
      let j = i + 1
      while (j < n && LETTER_OR_DIGIT.test(src[j])) j++
      tokens.push({ type: 'ident', value: src.slice(i, j) })
      i = j
      continue
    }

    const two = src.slice(i, i + 2)
    if (two === '<=' || two === '>=' || two === '<>') {
      tokens.push({ type: two, value: two })
      i += 2
      continue
    }

    if (SINGLE_PUNCT.includes(ch)) {
      tokens.push({ type: ch, value: ch })
      i++
      continue
    }

    throw new LexError(`unexpected character ${ch}`)
  }

  tokens.push({ type: 'eof', value: '' })
  return tokens
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZXBfV0/src/parser.js","content":"/**
 * Recursive-descent parser for a formula body, producing an AST.
 *
 * Precedence, loosest to tightest: comparisons, `+ -`, `* /`, `^`, leading
 * sign. Comparisons and the additive/multiplicative operators are
 * left-associative; `^` is right-associative and binds looser than a
 * leading sign, so `-2^2` is `(-2)^2`.
 *
 * A range (`A1:B3`) parses anywhere a cell address could stand, so that a
 * misplaced one still names its cells for `deps`; only a range that is
 * exactly a function call's argument (not wrapped in parentheses or an
 * operator) is marked `direct` and usable by `values`.
 */

import { tokenize } from './lexer.js'

export class ParseError extends Error {}

const COMPARISON_TYPES = new Set(['=', '<>', '<', '<=', '>', '>='])

export function parseFormula(src) {
  const tokens = tokenize(src)
  let pos = 0

  function peek() {
    return tokens[pos]
  }

  function advance() {
    return tokens[pos++]
  }

  function expect(type) {
    if (peek().type !== type) throw new ParseError(`expected ${type}`)
    return advance()
  }

  function parseComparison() {
    let left = parseAdditive()
    while (COMPARISON_TYPES.has(peek().type)) {
      const op = advance().type
      const right = parseAdditive()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    while (peek().type === '+' || peek().type === '-') {
      const op = advance().type
      const right = parseMultiplicative()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    while (peek().type === '*' || peek().type === '/') {
      const op = advance().type
      const right = parsePower()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  function parsePower() {
    const left = parseUnary()
    if (peek().type === '^') {
      advance()
      const right = parsePower()
      return { type: 'Binary', op: '^', left, right }
    }
    return left
  }

  function parseUnary() {
    if (peek().type === '-' || peek().type === '+') {
      const op = advance().type
      const expr = parseUnary()
      return { type: 'Unary', op, expr }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()

    if (t.type === 'number') {
      advance()
      return { type: 'Number', value: parseFloat(t.value) }
    }

    if (t.type === '(') {
      advance()
      const inner = parseComparison()
      expect(')')
      return { type: 'Paren', inner }
    }

    if (t.type === 'ident') {
      advance()
      const upper = t.value.toUpperCase()

      if (peek().type === '(') {
        advance()
        const args = []
        if (peek().type !== ')') {
          args.push(parseArg())
          while (peek().type === ',') {
            advance()
            args.push(parseArg())
          }
        }
        expect(')')
        return { type: 'Call', name: upper, args }
      }

      if (upper === 'TRUE' || upper === 'FALSE') {
        return { type: 'Bool', value: upper === 'TRUE' }
      }

      if (peek().type === ':') {
        advance()
        const bTok = peek()
        if (bTok.type !== 'ident') throw new ParseError('expected address after :')
        advance()
        return { type: 'Range', a: upper, b: bTok.value.toUpperCase(), direct: false }
      }

      return { type: 'Address', token: upper }
    }

    throw new ParseError(`unexpected token ${t.type}`)
  }

  // An argument to a function call: a bare range (marked direct) or any
  // other expression, which may itself contain a range in a non-direct
  // position.
  function parseArg() {
    const node = parseComparison()
    if (node.type === 'Range') node.direct = true
    return node
  }

  const result = parseComparison()
  expect('eof')
  return result
}
"}

