{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZXBfV0/src/evaluator.js","content":"/**
 * Evaluates a sheet's cells lazily, with memoization and cycle detection.
 *
 * A Value is one of:
 *   { k: 'num',  v: number }
 *   { k: 'text', v: string }
 *   { k: 'bool', v: boolean }
 *   { k: 'err',  v: string }   -- one of the error tokens
 */

import { parseAddress, addressToString, expandRange } from './address.js'
import { parseFormula, ParseError } from './parser.js'
import { LexError } from './lexer.js'
import { parseLiteral } from './literal.js'

const VARIADIC = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

export function makeEvaluator(sheet) {
  const cache = new Map()
  const visiting = new Set()

  function evalCellByKey(key) {
    if (cache.has(key)) return cache.get(key)
    if (visiting.has(key)) return { k: 'err', v: '#CYCLE!' }

    const entry = sheet.get(key)
    visiting.add(key)
    let result
    if (!entry) {
      result = { k: 'num', v: 0 }
    } else if (entry.content.startsWith('=')) {
      result = evalFormulaCell(entry.content)
    } else {
      result = parseLiteral(entry.content)
    }
    visiting.delete(key)
    cache.set(key, result)
    return result
  }

  function evalFormulaCell(content) {
    let ast
    try {
      ast = parseFormula(content.slice(1))
    } catch (e) {
      if (e instanceof ParseError || e instanceof LexError) return { k: 'err', v: '#ERR!' }
      throw e
    }
    return evalNode(ast)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'Number':
        return { k: 'num', v: node.value }
      case 'Bool':
        return { k: 'bool', v: node.value }
      case 'Paren':
        return evalNode(node.inner)
      case 'Address':
        return evalAddress(node.token)
      case 'Range':
        // Reached only when a range is not directly a function argument.
        return { k: 'err', v: '#ERR!' }
      case 'Unary':
        return evalUnary(node)
      case 'Binary':
        return evalBinary(node)
      case 'Call':
        return evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  function evalAddress(token) {
    const addr = parseAddress(token)
    if (!addr) return { k: 'err', v: '#REF!' }
    return evalCellByKey(addressToString(addr))
  }

  function evalUnary(node) {
    const n = toNumber(evalNode(node.expr))
    if (n.k === 'err') return n
    return numResult(node.op === '-' ? -n.v : n.v)
  }

  function evalBinary(node) {
    const left = evalNode(node.left)
    const right = evalNode(node.right)

    if (COMPARISON_OPS.has(node.op)) {
      if (left.k === 'err') return left
      if (right.k === 'err') return right
      return evalCompare(node.op, left, right)
    }

    if (left.k === 'err') return left
    if (right.k === 'err') return right
    const ln = toNumber(left)
    if (ln.k === 'err') return ln
    const rn = toNumber(right)
    if (rn.k === 'err') return rn

    switch (node.op) {
      case '+':
        return numResult(ln.v + rn.v)
      case '-':
        return numResult(ln.v - rn.v)
      case '*':
        return numResult(ln.v * rn.v)
      case '/':
        if (rn.v === 0) return { k: 'err', v: '#DIV/0!' }
        return numResult(ln.v / rn.v)
      case '^':
        return numResult(Math.pow(ln.v, rn.v))
      default:
        throw new Error(`unknown operator ${node.op}`)
    }
  }

  // Expands a direct-range function argument into its cell values, or
  // returns a single #REF! placeholder when either corner is out of range.
  function expandDirectRange(node) {
    const a = parseAddress(node.a)
    const b = parseAddress(node.b)
    if (!a || !b) return [{ k: 'err', v: '#REF!' }]
    return expandRange(a, b).map((c) => evalCellByKey(addressToString(c)))
  }

  // Evaluates a function argument that may be a direct range, flattening it
  // into a list of one or more values (in left-to-right, range-expanded
  // order).
  function flattenArgs(argNodes) {
    const values = []
    for (const arg of argNodes) {
      if (arg.type === 'Range' && arg.direct) {
        values.push(...expandDirectRange(arg))
      } else {
        values.push(evalNode(arg))
      }
    }
    return values
  }

  function evalCall(node) {
    const { name, args } = node

    if (VARIADIC.has(name)) {
      if (args.length < 1) return { k: 'err', v: '#ERR!' }
      return evalVariadic(name, flattenArgs(args))
    }

    if (name === 'ABS') {
      if (args.length !== 1) return { k: 'err', v: '#ERR!' }
      const values = flattenArgs(args)
      for (const v of values) if (v.k === 'err') return v
      const n = toNumber(values[0])
      if (n.k === 'err') return n
      return numResult(Math.abs(n.v))
    }

    if (name === 'IF') {
      if (args.length !== 3) return { k: 'err', v: '#ERR!' }
      return evalIf(args)
    }

    return { k: 'err', v: '#NAME?' }
  }

  function evalVariadic(name, values) {
    if (name === 'COUNT') {
      for (const v of values) if (v.k === 'err') return v
      return { k: 'num', v: values.filter((v) => v.k === 'num').length }
    }

    for (const v of values) if (v.k === 'err') return v
    const nums = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.k === 'err') return n
      nums.push(n.v)
    }

    switch (name) {
      case 'SUM':
        return numResult(nums.reduce((a, b) => a + b, 0))
      case 'MIN':
        return numResult(nums.reduce((a, b) => Math.min(a, b)))
      case 'MAX':
        return numResult(nums.reduce((a, b) => Math.max(a, b)))
      case 'AVG':
        return numResult(nums.reduce((a, b) => a + b, 0) / nums.length)
      default:
        throw new Error(`unknown variadic function ${name}`)
    }
  }

  function evalArgSingle(node) {
    if (node.type === 'Range' && node.direct) {
      const values = expandDirectRange(node)
      for (const v of values) if (v.k === 'err') return v
      return values[0]
    }
    return evalNode(node)
  }

  function evalIf(args) {
    const cond = evalArgSingle(args[0])
    if (cond.k === 'err') return cond
    const bool = toBoolCondition(cond)
    if (bool.k === 'err') return bool
    return evalArgSingle(bool.v ? args[1] : args[2])
  }

  return { evalCellByKey }
}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function toNumber(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return { k: 'num', v: v.v ? 1 : 0 }
  if (v.k === 'err') return v
  return { k: 'err', v: '#VALUE!' }
}

function toBoolCondition(v) {
  if (v.k === 'bool') return v
  if (v.k === 'num') return { k: 'bool', v: v.v !== 0 }
  if (v.k === 'err') return v
  return { k: 'err', v: '#VALUE!' }
}

function numResult(x) {
  if (!Number.isFinite(x)) return { k: 'err', v: '#DIV/0!' }
  return { k: 'num', v: x }
}

function kindRank(v) {
  if (v.k === 'num') return 0
  if (v.k === 'text') return 1
  return 2 // bool
}

function evalCompare(op, l, r) {
  let cmp
  if (l.k === r.k) {
    if (l.k === 'num') cmp = l.v - r.v
    else if (l.k === 'text') cmp = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
    else cmp = (l.v ? 1 : 0) - (r.v ? 1 : 0)
  } else {
    cmp = kindRank(l) - kindRank(r)
  }

  let result
  switch (op) {
    case '=':
      result = cmp === 0
      break
    case '<>':
      result = cmp !== 0
      break
    case '<':
      result = cmp < 0
      break
    case '<=':
      result = cmp <= 0
      break
    case '>':
      result = cmp > 0
      break
    case '>=':
      result = cmp >= 0
      break
    default:
      throw new Error(`unknown comparison ${op}`)
  }
  return { k: 'bool', v: result }
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-ZXBfV0/src/deps.js","content":"/**
 * Walks a formula's AST collecting every distinct in-range cell address it
 * names, ranges expanded, regardless of where in the formula it appears --
 * `deps` is purely syntactic and does not evaluate the formula.
 */

import { parseAddress, addressToString, compareAddresses, expandRange } from './address.js'

export function collectDeps(ast) {
  const found = new Map()

  function addToken(token) {
    const addr = parseAddress(token)
    if (addr) found.set(addressToString(addr), addr)
  }

  function addRange(node) {
    const a = parseAddress(node.a)
    const b = parseAddress(node.b)
    if (!a || !b) return
    for (const c of expandRange(a, b)) found.set(addressToString(c), c)
  }

  function walk(node) {
    switch (node.type) {
      case 'Number':
      case 'Bool':
        return
      case 'Address':
        addToken(node.token)
        return
      case 'Range':
        addRange(node)
        return
      case 'Paren':
        walk(node.inner)
        return
      case 'Unary':
        walk(node.expr)
        return
      case 'Binary':
        walk(node.left)
        walk(node.right)
        return
      case 'Call':
        node.args.forEach(walk)
        return
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  walk(ast)
  return [...found.values()].sort(compareAddresses)
