{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-Zl7JVV/src/policies.js","content":"/**
 * Per-key state machines for the two limiter kinds. Each policy keeps one
 * independent state per key, created lazily the first time that key reaches
 * it, and exposes the three operations the simulator needs: advance to a
 * tick, check whether a request is currently allowed, and record one.
 */

/** A token bucket: refills continuously, spends one whole token per request. */
export class Bucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // Tokens are tracked as an exact fraction with denominator `per`, stored
    // as `numerator / per`, so partial refills never lose precision.
    this.capacityNumerator = capacity * per
    this.states = new Map() // key -> { numerator, lastTick }
  }

  #state(key, tick) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { numerator: this.capacityNumerator, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key, tick)
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      state.numerator += this.refill * elapsed
      if (state.numerator > this.capacityNumerator) state.numerator = this.capacityNumerator
      state.lastTick = tick
    }
  }

  allows(key) {
    const state = this.states.get(key)
    return state.numerator >= this.per
  }

  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

/** A sliding window: remembers the ticks of the requests it recorded. */
export class Window {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map() // key -> tick[] (ascending, since ticks never go backwards)
  }

  #state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#state(key)
    const cutoff = tick - this.span
    let drop = 0
    while (drop < state.length && state[drop] <= cutoff) drop++
    if (drop > 0) state.splice(0, drop)
  }

  allows(key) {
    const state = this.states.get(key)
    return BigInt(state.length) < this.limit
  }

  record(key) {
    const state = this.states.get(key)
    state.push(this._lastTick)
  }

  advanceAndRemember(key, tick) {
    // advance() drops expired ticks; record() needs the current tick, so we
    // stash it here rather than threading the tick through allows()/record().
    this.advance(key, tick)
    this._lastTick = tick
  }
}
"}

