// A name, a route prefix and an event key share this character set.
const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/

// An unsigned decimal integer: no sign, and no leading zero unless it is 0.
const INTEGER_RE = /^(0|[1-9][0-9]*)$/

export function isToken(value) {
  return TOKEN_RE.test(value)
}

export function parseIntField(value, fieldName, minimum) {
  if (!INTEGER_RE.test(value) || BigInt(value) < minimum) {
    throw new CliError(`${fieldName} must be an integer of at least ${minimum}`)
  }
  return BigInt(value)
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-do6S5w/src/policies.js","content":"/**
 * A token bucket that holds `capacity` tokens, refills `refill` tokens for
 * every `per` ticks that pass, and keeps one independent state per key.
 * Tokens are tracked in units of `per` (a bucket holding a whole token holds
 * at least `per` units) so that partial refill periods never need rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map()
  }

  advance(key, tick) {
    const state = this.states.get(key)
    if (!state) {
      this.states.set(key, { lastTick: tick, unitsNum: this.capacity * this.per })
      return
    }
    const elapsed = tick - state.lastTick
    if (elapsed > 0n) {
      const capNum = this.capacity * this.per
      state.unitsNum += this.refill * elapsed
      if (state.unitsNum > capNum) state.unitsNum = capNum
      state.lastTick = tick
    }
  }

  allow(key) {
    return this.states.get(key).unitsNum >= this.per
  }

  record(key) {
    this.states.get(key).unitsNum -= this.per
  }
}

/**
 * A sliding window that remembers the ticks of the requests it recorded for
 * a key, forgetting anything at or before `tick - span` on each advance.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  advance(key, tick) {
    let ticks = this.states.get(key)
    if (!ticks) {
      ticks = []
      this.states.set(key, ticks)
    }
    const threshold = tick - this.span
    while (ticks.length > 0 && ticks[0] <= threshold) ticks.shift()
  }

  allow(key) {
    return BigInt(this.states.get(key).length) < this.limit
  }

  record(key, tick) {
    this.states.get(key).push(tick)
  }
}
"}

