{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-do6S5w/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { CliError } from './cliError.js'
import { simulate } from './parser.js'

const mode = process.argv[2]
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

const input = readFileSync(0, 'utf8')

let result
try {
  result = simulate(input)
} catch (error) {
  if (error instanceof CliError) {
    process.stderr.write(`error: ${error.message}\n`)
    process.exit(2)
  }
  throw error
}

if (mode === 'replay') {
  const lines = result.events.map(({ tick, key, allowed, denyPolicy }) =>
    allowed ? `${tick} ${key} allow` : `${tick} ${key} deny ${denyPolicy}`
  )
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
} else {
  const totals = new Map()
  for (const { key, allowed } of result.events) {
    let entry = totals.get(key)
    if (!entry) {
      entry = { allowed: 0n, denied: 0n }
      totals.set(key, entry)
    }
    if (allowed) entry.allowed += 1n
    else entry.denied += 1n
  }

  let totalAllowed = 0n
  let totalDenied = 0n
  const lines = []
  for (const key of [...totals.keys()].sort()) {
    const { allowed, denied } = totals.get(key)
    totalAllowed += allowed
    totalDenied += denied
    lines.push(`${key} allowed=${allowed} denied=${denied}\n`)
  }
  lines.push(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  process.stdout.write(lines.join(''))
}
"}

