{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-jUBhKt/src/lexer.js","content":"/**
 * Scans UTF-8 source text into a flat list of tokens, or throws a
 * LexError carrying the 1-based line/column and reason of the first
 * character sequence the grammar in the task description rejects.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

class LexError extends Error {
  constructor(reason, line, col) {
    super(reason)
    this.dshLexError = true
    this.reason = reason
    this.line = line
    this.col = col
  }
}

function isDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isLetter(c) {
  return c !== undefined && /\p{L}/u.test(c)
}

function isIdentPart(c) {
  return c !== undefined && (isLetter(c) || isDigit(c) || c === '_')
}

export function tokenize(text) {
  const chars = Array.from(text)
  const len = chars.length
  let i = 0
  let line = 1
  let col = 1

  function pos() {
    return { line, col }
  }

  function peek(offset = 0) {
    return chars[i + offset]
  }

  function advance() {
    const c = chars[i]
    i++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else {
      col++
    }
    return c
  }

  function fail(reason, p) {
    throw new LexError(reason, p.line, p.col)
  }

  function sliceText(start, end) {
    return chars.slice(start, end).join('')
  }

  function skipBlockComment() {
    const start = pos()
    advance()
    advance()
    let depth = 1
    while (depth > 0) {
      if (i >= len) fail('unterminated block comment', start)
      const c = peek()
      if (c === '/' && peek(1) === '*') {
        advance()
        advance()
        depth++
        continue
      }
      if (c === '*' && peek(1) === '/') {
        advance()
        advance()
        depth--
        continue
      }
      advance()
    }
  }

  function skipTrivia() {
    while (i < len) {
      const c = peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
        continue
      }
      if (c === '/' && peek(1) === '/') {
        advance()
        advance()
        while (i < len && peek() !== '\n') advance()
        continue
      }
      if (c === '/' && peek(1) === '*') {
        skipBlockComment()
        continue
      }
      break
    }
  }

  function consumeDigitRun(isDigitFn) {
    let count = 0
    while (true) {
      const c = peek()
      if (c !== undefined && isDigitFn(c)) {
        advance()
        count++
        continue
      }
      if (c === '_' && count > 0 && isDigitFn(peek(1))) {
        advance()
        continue
      }
      break
    }
    return count
  }

  function scanIdentifier() {
    const start = pos()
    const startIdx = i
    advance()
    while (isIdentPart(peek())) advance()
    const text = sliceText(startIdx, i)
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, line: start.line, col: start.col }
  }

  function scanNumber() {
    const start = pos()
    const startIdx = i
    let invalid = false

    const c0 = peek()
    const c1 = peek(1)
    if (c0 === '0' && (c1 === 'x' || c1 === 'X' || c1 === 'b' || c1 === 'B' || c1 === 'o' || c1 === 'O')) {
      advance()
      const p = advance()
      let isDigitFn
      if (p === 'x' || p === 'X') isDigitFn = isHexDigit
      else if (p === 'b' || p === 'B') isDigitFn = (c) => c === '0' || c === '1'
      else isDigitFn = (c) => c !== undefined && c >= '0' && c <= '7'
      const count = consumeDigitRun(isDigitFn)
