 * Evaluates a parsed formula AST against a sheet, with cycle detection and
 * memoization of formula cells.
 */

import { parseAddress, cellKey } from './address.js'
import { numV, boolV, errV, toNumber, toCondition, compareValues } from './values.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function evalBinOp(op, l, r) {
  if (l.t === 'err') return l
  if (r.t === 'err') return r
  if (COMPARISON_OPS.has(op)) {
    const c = compareValues(l, r)
    const res = op === '=' ? c === 0
      : op === '<>' ? c !== 0
      : op === '<' ? c < 0
      : op === '<=' ? c <= 0
      : op === '>' ? c > 0
      : c >= 0
    return boolV(res)
  }
  const ln = toNumber(l)
  if (!ln.ok) return ln.err
  const rn = toNumber(r)
  if (!rn.ok) return rn.err
  const result = op === '+' ? ln.n + rn.n
    : op === '-' ? ln.n - rn.n
    : op === '*' ? ln.n * rn.n
    : op === '/' ? ln.n / rn.n
    : Math.pow(ln.n, rn.n)
  return Number.isFinite(result) ? numV(result) : errV('#DIV/0!')
}

function evalUnary(op, val) {
  if (val.t === 'err') return val
  const n = toNumber(val)
  if (!n.ok) return n.err
  const result = op === '-' ? -n.n : n.n
  return Number.isFinite(result) ? numV(result) : errV('#DIV/0!')
}

function getCellValue(ctx, col, row) {
  const key = cellKey(col, row)
  const cell = ctx.sheet.get(key)
  if (!cell) return numV(0)
  if (cell.kind === 'literal') return cell.value
  if (!cell.ast) return errV('#ERR!')
  if (cell.state === 'visiting') return errV('#CYCLE!')
  if (cell.state === 'done') return cell.value
  cell.state = 'visiting'
  const val = evaluateNode(cell.ast, ctx)
  cell.state = 'done'
  cell.value = val
  return val
}

function expandRange(node, ctx) {
  const a = parseAddress(node.from)
  const b = parseAddress(node.to)
  if (!a.valid || !b.valid) return [errV('#REF!')]
  const c1 = Math.min(a.col, b.col)
  const c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row)
  const r2 = Math.max(a.row, b.row)
  const vals = []
  for (let c = c1; c <= c2; c++) {
    for (let r = r1; r <= r2; r++) vals.push(getCellValue(ctx, c, r))
  }
  return vals
}

function valuesOf(node, ctx) {
  return node.type === 'range' ? expandRange(node, ctx) : [evaluateNode(node, ctx)]
}

function firstError(vals) {
  for (const v of vals) if (v.t === 'err') return v
  return null
}

const ARITIES = { SUM: '+', MIN: '+', MAX: '+', COUNT: '+', AVG: '+', ABS: 1, IF: 3 }

function evalCall(name, args, ctx) {
  const arity = ARITIES[name]
  if (arity === undefined) return errV('#NAME?')

  if (arity === 3) {
    if (args.length !== 3) return errV('#ERR!')
