  if (args.length < 1) return errV('#ERR!')
  const allVals = []
  for (const a of args) allVals.push(...valuesOf(a, ctx))
  const err = firstError(allVals)
  if (err) return err

  if (name === 'COUNT') return numV(allVals.filter((v) => v.t === 'num').length)

  const nums = []
  for (const v of allVals) {
    const n = toNumber(v)
    if (!n.ok) return n.err
    nums.push(n.n)
  }
  const result = name === 'SUM' ? nums.reduce((a, b) => a + b, 0)
    : name === 'AVG' ? nums.reduce((a, b) => a + b, 0) / nums.length
    : name === 'MIN' ? Math.min(...nums)
    : Math.max(...nums)
  return Number.isFinite(result) ? numV(result) : errV('#DIV/0!')
}

function evaluateNode(node, ctx) {
  switch (node.type) {
    case 'number': return numV(node.value)
    case 'bool': return boolV(node.value)
    case 'address': {
      const a = parseAddress(node.raw)
      return a.valid ? getCellValue(ctx, a.col, a.row) : errV('#REF!')
    }
    case 'unary': return evalUnary(node.op, evaluateNode(node.expr, ctx))
    case 'binop': return evalBinOp(node.op, evaluateNode(node.left, ctx), evaluateNode(node.right, ctx))
    case 'call': return evalCall(node.name, node.args, ctx)
    default: throw new Error(`unexpected node type ${node.type}`)
  }
}

/** Evaluates the cell at (col, row) in the given sheet context. */
export function evaluateCell(ctx, col, row) {
  return getCellValue(ctx, col, row)
}
