{"file_path":"src/deps.js","content":"/**
 * Static dependency extraction: walks a parsed formula AST (without
 * evaluating anything) and collects every distinct in-range address the
 * formula names directly, ranges expanded. A cell whose formula failed to
 * parse, or that is a literal, names nothing.
 */

import { parseAddress, cellKey, addressString } from './address.js'

function addAddr(set, raw) {
  const a = parseAddress(raw)
  if (a.valid) set.set(cellKey(a.col, a.row), a)
}

function addRange(set, from, to) {
  const a = parseAddress(from)
  const b = parseAddress(to)
  if (!a.valid || !b.valid) return
  const c1 = Math.min(a.col, b.col)
  const c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row)
  const r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) {
    for (let r = r1; r <= r2; r++) set.set(cellKey(c, r), { col: c, row: r })
  }
}

function walk(node, set) {
  switch (node.type) {
    case 'number':
    case 'bool':
      return
    case 'address':
      addAddr(set, node.raw)
      return
    case 'unary':
      walk(node.expr, set)
      return
    case 'binop':
      walk(node.left, set)
      walk(node.right, set)
      return
    case 'call':
      for (const arg of node.args) walk(arg, set)
      return
    case 'range':
      addRange(set, node.from, node.to)
      return
    default:
      throw new Error(`unexpected node type ${node.type}`)
  }
}

/** Returns the addresses a formula AST names, ordered by column then row. */
export function collectDeps(ast) {
  const set = new Map()
  walk(ast, set)
  return [...set.values()]
    .sort((a, b) => (a.col - b.col) || (a.row - b.row))
    .map((a) => addressString(a.col, a.row))
}
"}

