/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { evaluateCell } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './values.js'
import { addressString } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const cells = [...sheet.values()].sort((a, b) => (a.col - b.col) || (a.row - b.row))
  const ctx = { sheet }

  const lines = cells.map((cell) => {
    const addr = addressString(cell.col, cell.row)
    if (mode === 'values') {
      const value = evaluateCell(ctx, cell.col, cell.row)
      return `${addr}=${formatValue(value)}`
    }
    const deps = cell.kind === 'formula' && cell.ast ? collectDeps(cell.ast) : []
    return `${addr}:${deps.map((d) => ` ${d}`).join('')}`
  })

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
}

main()
"}

