{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-n4wZWQ/src/parser.js","content":"/**
 * Recursive-descent parser for a formula body's token stream.
 *
 * Precedence, loosest first: comparisons, then `+`/`-`, then `*`/`/`, then
 * `^`, then a leading unary `-`/`+`. Comparisons and the additive and
 * multiplicative operators group to the left; `^` groups to the right and
 * a leading sign binds tighter than `^` (applies only to the primary it
 * precedes, not to the whole power chain).
 *
 * A range (`A1:B3`) is a grammar-level primary wherever an address may
 * appear; the caller decides whether the position it landed in is a valid
 * one (directly as a call argument) or not (anything else, which the
 * evaluator turns into `#ERR!`).
 */

import { tokenize, LexError } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

class ParseError extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  parseProgram() {
    const expr = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return expr
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'cmp', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const base = this.parseUnary()
    if (this.peek() && this.peek().type === 'OP' && this.peek().value === '^') {
      this.next()
      const exp = this.parsePower()
      return { type: 'pow', base, exp }
    }
    return base
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'OP' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new ParseError('unexpected end of formula')
    if (t.type === 'NUMBER') {
      this.next()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === 'LPAREN') {
      this.next()
      const inner = this.parseComparison()
      this.expect('RPAREN')
      return inner
    }
    if (t.type === 'WORD') {
      this.next()
      const upper = t.value.toUpperCase()
      if (this.peek() && this.peek().type === 'LPAREN') {
        this.next()
        const args = this.parseArgs()
        this.expect('RPAREN')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE' || upper === 'FALSE') {
        return { type: 'bool', value: upper === 'TRUE' }
      }
      if (this.peek() && this.peek().type === 'COLON') {
        this.next()
        const toTok = this.expect('WORD')
        return { type: 'range', from: upper, to: toTok.value.toUpperCase() }
      }
      return { type: 'addr', name: upper }
    }
    throw new ParseError('unexpected token')
  }

  parseArgs() {
    const args = []
    if (this.peek() && this.peek().type === 'RPAREN') return args
    args.push(this.parseComparison())
    while (this.peek() && this.peek().type === 'COMMA') {
      this.next()
      args.push(this.parseComparison())
    }
    return args
  }
}

/**
 * Parses a formula body (without the leading `=`). Returns the AST, or null
 * when the body is not accepted by the grammar.
 */
export function parseFormula(body) {
  let tokens
  try {
    tokens = tokenize(body)
  } catch (e) {
    if (e instanceof LexError) return null
    throw e
  }
  try {
    const parser = new Parser(tokens)
    return parser.parseProgram()
  } catch (e) {
    if (e instanceof ParseError) return null
    throw e
  }
}
