 * Evaluates a sheet's cells, with memoization and cycle detection, plus
 * literal parsing and the formula function library.
 */

import { addressInfo, expandRange } from './address.js'
import { parseFormula } from './parser.js'
import { num, text, bool, err, isErr, toNumber, finiteOrDivZero, compareValues } from './values.js'

const NUMBER_LITERAL_RE = /^-?[0-9]+(\.[0-9]+)?$/
const ERROR_TOKEN_SET = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

/** Parses a non-formula cell's raw content into a value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_LITERAL_RE.test(content)) return num(parseFloat(content))
  if (ERROR_TOKEN_SET.has(content)) return err(content)
  return text(content)
}

/**
 * Creates an evaluation context for a sheet (a Map from canonical address
 * to its raw content string) that memoizes per-cell results and detects
 * cycles.
 */
export function createContext(cells) {
  return { cells, cache: new Map(), visiting: new Set() }
}

/** Evaluates the cell at a canonical address, using the context's cache. */
export function evalCell(addr, ctx) {
  if (ctx.cache.has(addr)) return ctx.cache.get(addr)
  if (ctx.visiting.has(addr)) return err('#CYCLE!')
  const cell = ctx.cells.get(addr)
  if (!cell) {
    const v = num(0)
    ctx.cache.set(addr, v)
    return v
  }
  ctx.visiting.add(addr)
  let result
  try {
    result = evalContent(cell.content, ctx)
  } finally {
    ctx.visiting.delete(addr)
  }
  ctx.cache.set(addr, result)
  return result
}

function evalContent(content, ctx) {
  if (content.startsWith('=')) {
    const ast = parseFormula(content.slice(1))
    if (!ast) return err('#ERR!')
    return evalExpr(ast, ctx)
  }
  return parseLiteral(content)
}

function evalAddrNode(node, ctx) {
  const info = addressInfo(node.name)
  if (!info.valid) return err('#REF!')
  return evalCell(info.text, ctx)
}

/**
 * Expands a range AST node to its covered addresses, or a #REF! error when
 * an endpoint is outside the addressable range.
 */
function expandRangeNode(node) {
  const r = expandRange(node.from, node.to)
  if (!r.ok) return { ok: false, error: err('#REF!') }
  return { ok: true, addresses: r.addresses }
}

/**
 * Evaluates a call argument that must reduce to a single scalar value
 * (used by ABS and IF). A range argument is only meaningful when it covers
 * exactly one cell; any error among its cells wins, and a wider range is
 * an #ERR! since it cannot be read as one value.
 */
function scalarFromArg(argNode, ctx) {
  if (argNode.type === 'range') {
    const exp = expandRangeNode(argNode)
    if (!exp.ok) return exp.error
    const vals = exp.addresses.map((a) => evalCell(a, ctx))
    for (const v of vals) if (isErr(v)) return v
    if (vals.length === 1) return vals[0]
    return err('#ERR!')
  }
  return evalExpr(argNode, ctx)
}

function evalAggregate(name, argNodes, ctx) {
  const values = []
  for (const argNode of argNodes) {
    if (argNode.type === 'range') {
      const exp = expandRangeNode(argNode)
      if (!exp.ok) {
        values.push(exp.error)
        continue
      }
      for (const a of exp.addresses) values.push(evalCell(a, ctx))
    } else {
      values.push(evalExpr(argNode, ctx))
    }
  }
  if (name === 'COUNT') {
    for (const v of values) if (isErr(v)) return v
    let count = 0
    for (const v of values) if (v.kind === 'num') count++
    return num(count)
  }
  const nums = []
  for (const v of values) {
    const r = toNumber(v)
    if (!r.ok) return r.err
    nums.push(r.n)
  }
  let result
  if (name === 'SUM') result = nums.reduce((a, b) => a + b, 0)
  else if (name === 'MIN') result = Math.min(...nums)
  else if (name === 'MAX') result = Math.max(...nums)
  else result = nums.reduce((a, b) => a + b, 0) / nums.length // AVG
  return finiteOrDivZero(result)
}

function evalAbs(argNodes, ctx) {
  if (argNodes.length !== 1) return err('#ERR!')
  const v = scalarFromArg(argNodes[0], ctx)
  if (isErr(v)) return v
  const r = toNumber(v)
  if (!r.ok) return r.err
  return finiteOrDivZero(Math.abs(r.n))
}

function evalIf(argNodes, ctx) {
  if (argNodes.length !== 3) return err('#ERR!')
  const cond = scalarFromArg(argNodes[0], ctx)
  if (isErr(cond)) return cond
  let branch
  if (cond.kind === 'bool') branch = argNodes[cond.v ? 1 : 2]
  else if (cond.kind === 'num') branch = argNodes[cond.v !== 0 ? 1 : 2]
  else return err('#VALUE!')
  return scalarFromArg(branch, ctx)
}

function evalCall(node, ctx) {
  switch (node.name) {
    case 'SUM':
    case 'MIN':
    case 'MAX':
    case 'AVG':
    case 'COUNT':
      if (node.args.length < 1) return err('#ERR!')
      return evalAggregate(node.name, node.args, ctx)
    case 'ABS':
      return evalAbs(node.args, ctx)
    case 'IF':
      return evalIf(node.args, ctx)
    default:
      return err('#NAME?')
  }
}

/** Evaluates a formula AST node to a value. */
export function evalExpr(node, ctx) {
  switch (node.type) {
    case 'num':
      return num(node.value)
    case 'bool':
      return bool(node.value)
    case 'addr':
      return evalAddrNode(node, ctx)
    case 'range':
      return err('#ERR!') // a range is only valid directly as a call argument
    case 'unary': {
      const v = evalExpr(node.operand, ctx)
      if (isErr(v)) return v
      const r = toNumber(v)
      if (!r.ok) return r.err
      return finiteOrDivZero(node.op === '-' ? -r.n : r.n)
    }
    case 'pow': {
      const b = evalExpr(node.base, ctx)
      if (isErr(b)) return b
      const e = evalExpr(node.exp, ctx)
      if (isErr(e)) return e
      const bn = toNumber(b)
      if (!bn.ok) return bn.err
      const en = toNumber(e)
      if (!en.ok) return en.err
      return finiteOrDivZero(Math.pow(bn.n, en.n))
    }
    case 'bin': {
      const left = evalExpr(node.left, ctx)
      if (isErr(left)) return left
      const right = evalExpr(node.right, ctx)
      if (isErr(right)) return right
      const ln = toNumber(left)
      if (!ln.ok) return ln.err
      const rn = toNumber(right)
      if (!rn.ok) return rn.err
      if (node.op === '/') {
        if (rn.n === 0) return err('#DIV/0!')
        return finiteOrDivZero(ln.n / rn.n)
      }
      if (node.op === '+') return finiteOrDivZero(ln.n + rn.n)
      if (node.op === '-') return finiteOrDivZero(ln.n - rn.n)
      return finiteOrDivZero(ln.n * rn.n) // '*'
    }
    case 'cmp': {
      const left = evalExpr(node.left, ctx)
      if (isErr(left)) return left
      const right = evalExpr(node.right, ctx)
      if (isErr(right)) return right
      const c = compareValues(left, right)
      switch (node.op) {
        case '=':
          return bool(c === 0)
        case '<>':
          return bool(c !== 0)
        case '<':
          return bool(c < 0)
        case '<=':
          return bool(c <= 0)
        case '>':
          return bool(c > 0)
        default:
          return bool(c >= 0) // '>='
      }
    }
    case 'call':
      return evalCall(node, ctx)
    default:
      throw new Error(`unknown AST node type ${node.type}`)
  }
}
"}

