import { addressInfo, expandRange } from './address.js'
import { parseFormula } from './parser.js'

function collect(node, set) {
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'addr': {
      const info = addressInfo(node.name)
      if (info.valid) set.add(info.text)
      return
    }
    case 'range': {
      const r = expandRange(node.from, node.to)
      if (r.ok) for (const a of r.addresses) set.add(a)
      return
    }
    case 'unary':
      collect(node.operand, set)
      return
    case 'pow':
      collect(node.base, set)
      collect(node.exp, set)
      return
    case 'bin':
    case 'cmp':
      collect(node.left, set)
      collect(node.right, set)
      return
    case 'call':
      for (const a of node.args) collect(a, set)
      return
    default:
      throw new Error(`unknown AST node type ${node.type}`)
  }
}

