 * Returns the set of distinct addresses a cell's content names directly.
 * A literal, or a formula the grammar rejects, names none.
 */
export function collectDeps(content) {
  const set = new Set()
  if (!content.startsWith('=')) return set
  const ast = parseFormula(content.slice(1))
  if (!ast) return set
  collect(ast, set)
  return set
}
"}

