 * Parses a sheet's raw text into an ordered map of canonical address to
 * declared content, per the line-splitting and address-declaration rules.
 */

import { addressInfo, compareAddresses } from './address.js'

/** Raised for a malformed sheet; carries the 1-based line number. */
export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

function splitAddressAndContent(trimmedLine) {
  const idx = trimmedLine.search(/[ \t]/)
  if (idx === -1) return { addressToken: trimmedLine, content: '' }
  const addressToken = trimmedLine.slice(0, idx)
  let j = idx
  while (j < trimmedLine.length && (trimmedLine[j] === ' ' || trimmedLine[j] === '\t')) j++
  return { addressToken, content: trimmedLine.slice(j) }
}

/**
 * Parses sheet text into a Map from canonical address (e.g. "A1") to
 * { content, line }, in ascending column-then-row order. Throws SheetError
 * on an invalid or duplicate address.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  lines.forEach((rawLine, i) => {
    const lineNo = i + 1
    const trimmed = rawLine.replace(/^[ \t]+/, '')
    if (trimmed === '' || trimmed[0] === '#') return

    const { addressToken, content } = splitAddressAndContent(trimmed)
    const info = addressInfo(addressToken)
    if (!info.valid) throw new SheetError(lineNo, `invalid cell address ${addressToken}`)
    if (cells.has(info.text)) throw new SheetError(lineNo, `cell ${info.text} is declared twice`)
    cells.set(info.text, { content, line: lineNo })
  })

  const ordered = new Map([...cells.entries()].sort((a, b) => compareAddresses(a[0], b[0])))
  return ordered
}
"}

