 * URI reference parsing, normalization and resolution per RFC 3986,
 * restricted to the generic syntax as specified for this program.
 */

export class UriError extends Error {}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

/** Parse a URI reference into its five generic components. */
export function parseUriReference(str) {
  let rest = str
  let scheme = null
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i]
    if (c === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let authority = null
  if (rest.startsWith('//')) {
    let j = 2
    for (; j < rest.length; j++) {
      const c = rest[j]
      if (c === '/' || c === '?' || c === '#') break
    }
    authority = rest.slice(2, j)
    rest = rest.slice(j)
  }

  let pathEnd = rest.length
  for (let k = 0; k < rest.length; k++) {
    if (rest[k] === '?' || rest[k] === '#') {
      pathEnd = k
      break
    }
  }
  const path = rest.slice(0, pathEnd)
  rest = rest.slice(pathEnd)

  let query = null
  if (rest.startsWith('?')) {
    let fragIdx = rest.indexOf('#')
    if (fragIdx === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, fragIdx)
      rest = rest.slice(fragIdx)
    }
  }

  let fragment = null
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Split an authority component into userinfo, host and port. */
export function parseAuthority(authority) {
  let userinfo = null
  let hostport = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    hostport = authority.slice(atIdx + 1)
  }
  const bracketIdx = hostport.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = hostport.indexOf(':', searchFrom)
  let host, port
  if (colonIdx !== -1) {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  } else {
    host = hostport
    port = null
  }
  return { userinfo, host, port }
}

function serializeAuthority({ userinfo, host, port }) {
  let out = ''
  if (userinfo !== null) out += userinfo + '@'
  out += host
  if (port !== null) out += ':' + port
  return out
}

/** Serialize the five generic components back into a URI reference string. */
export function serialize({ scheme, authority, path, query, fragment }) {
  let out = ''
  if (scheme !== null) out += scheme + ':'
  if (authority !== null) out += '//' + authority
  out += path
  if (query !== null) out += '?' + query
  if (fragment !== null) out += '#' + fragment
  return out
}

const UNRESERVED = /[A-Za-z0-9\-._~]/
const HEX_PAIR = /^[0-9A-Fa-f]{2}$/

/**
 * Uppercase the hex digits of every %XX triplet and decode it when the
 * character it encodes is unreserved. Throws UriError naming `component`
 * when a `%` is not followed by two hexadecimal digits.
 */
function normalizePercentEncoding(str, component) {
  let out = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (!HEX_PAIR.test(hex)) {
        throw new UriError(`the ${component} has a truncated percent-encoding`)
      }
      const upper = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      out += UNRESERVED.test(ch) ? ch : '%' + upper
      i += 2
    } else {
      out += str[i]
    }
  }
  return out
}

function asciiLower(str) {
  return str.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/** Remove dot segments from a path per RFC 3986 section 5.2.4. */
export function removeDotSegments(path) {
  let input = path
  let output = ''
  const dropLastSegment = () => {
    const idx = output.lastIndexOf('/')
    output = idx === -1 ? '' : output.slice(0, idx)
  }
  while (input !== '') {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      dropLastSegment()
    } else if (input === '/..') {
      input = '/'
      dropLastSegment()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx
      if (input[0] === '/') {
        idx = input.indexOf('/', 1)
      } else {
        idx = input.indexOf('/')
      }
      if (idx === -1) idx = input.length
      output += input.slice(0, idx)
      input = input.slice(idx)
    }
  }
  return output
}

/** Normalize a parsed URI reference into a canonical string form. */
export function normalizeComponents(components) {
  const scheme = components.scheme === null ? null : asciiLower(components.scheme)

  const path = normalizePercentEncoding(components.path, 'path')

  let userinfo = null
  let host = null
  let port = null
  if (components.authority !== null) {
    const parsed = parseAuthority(components.authority)
    userinfo = parsed.userinfo === null ? null : normalizePercentEncoding(parsed.userinfo, 'userinfo')
    host = normalizePercentEncoding(parsed.host, 'host')
    port = parsed.port
  }

  const query = components.query === null ? null : normalizePercentEncoding(components.query, 'query')
  const fragment = components.fragment === null ? null : normalizePercentEncoding(components.fragment, 'fragment')

  if (host !== null) host = asciiLower(host)

  if (components.authority !== null) {
    const defaultPort = scheme === null ? undefined : DEFAULT_PORTS[scheme]
    if (port === '' || (defaultPort !== undefined && port === defaultPort)) {
      port = null
    }
  }

  let normalizedPath = removeDotSegments(path)

  const authority = components.authority === null ? null : serializeAuthority({ userinfo, host, port })

  if (authority !== null && normalizedPath === '') {
    normalizedPath = '/'
  }

  return serialize({ scheme, authority, path: normalizedPath, query, fragment })
}

/** Parse and normalize a URI reference string. */
export function normalize(str) {
  return normalizeComponents(parseUriReference(str))
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) return refPath
  return base.path.slice(0, lastSlash + 1) + refPath
}

