{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-r5tNq4/src/uri.js","content":"/**
 * Parsing, normalization and resolution of URI references, per RFC 3986's
 * generic syntax (section 3), percent-encoding normalization (section 6.2.2),
 * dot-segment removal (section 5.2.4) and reference resolution (section
 * 5.2.2, strict form).
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Thrown for a malformed record; its message already reads "line N: ...". */
export class UriError extends Error {}

/**
 * Splits a URI reference into its five generic components. An absent
 * component is `undefined`; an empty one is `''`.
 */
function parseReference(text) {
  let rest = text
  let scheme

  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (c === ':') {
      scheme = text.slice(0, i)
      rest = text.slice(i + 1)
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let authority
  if (rest.startsWith('//')) {
    const afterSlashes = rest.slice(2)
    let end = afterSlashes.length
    for (let i = 0; i < afterSlashes.length; i++) {
      const c = afterSlashes[i]
      if (c === '/' || c === '?' || c === '#') {
        end = i
        break
      }
    }
    authority = afterSlashes.slice(0, end)
    rest = afterSlashes.slice(end)
  }

  const qIdx = rest.indexOf('?')
  const hIdx = rest.indexOf('#')
  let path, query, fragment

  if (hIdx === -1) {
    if (qIdx === -1) {
      path = rest
    } else {
      path = rest.slice(0, qIdx)
      query = rest.slice(qIdx + 1)
    }
  } else if (qIdx !== -1 && qIdx < hIdx) {
    path = rest.slice(0, qIdx)
    query = rest.slice(qIdx + 1, hIdx)
    fragment = rest.slice(hIdx + 1)
  } else {
    path = rest.slice(0, hIdx)
    fragment = rest.slice(hIdx + 1)
  }

  return { scheme, authority, path, query, fragment }
}

/** Splits an authority string into userinfo, host and port. */
function parseAuthority(authority) {
  const atIdx = authority.lastIndexOf('@')
  const userinfo = atIdx === -1 ? undefined : authority.slice(0, atIdx)
  const hostport = atIdx === -1 ? authority : authority.slice(atIdx + 1)

  const bracketIdx = hostport.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = hostport.indexOf(':', searchFrom)

  const host = colonIdx === -1 ? hostport : hostport.slice(0, colonIdx)
  const port = colonIdx === -1 ? undefined : hostport.slice(colonIdx + 1)

  return { userinfo, host, port }
}

function isHexDigit(c) {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

function isUnreserved(ch) {
  return (
    (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') ||
    (ch >= '0' && ch <= '9') ||
    ch === '-' ||
    ch === '.' ||
    ch === '_' ||
    ch === '~'
  )
}

/**
 * Uppercases the hex digits of every `%XX` in `component` and decodes the
 * ones that spell an unreserved character. Throws when a `%` is not
 * followed by two hex digits.
 */
function normalizePercent(component, label, lineNum) {
  if (component === undefined) return undefined
  let out = ''
  for (let i = 0; i < component.length; i++) {
    const c = component[i]
    if (c !== '%') {
      out += c
      continue
    }
    const d1 = component[i + 1]
    const d2 = component[i + 2]
    if (d1 === undefined || d2 === undefined || !isHexDigit(d1) || !isHexDigit(d2)) {
      throw new UriError(`line ${lineNum}: the ${label} has a truncated percent-encoding`)
    }
    const hex = (d1 + d2).toUpperCase()
    const ch = String.fromCharCode(parseInt(hex, 16))
    out += isUnreserved(ch) ? ch : '%' + hex
    i += 2
  }
  return out
}

function asciiLowercase(s) {
  let out = ''
  for (const c of s) {
    out += c >= 'A' && c <= 'Z' ? c.toLowerCase() : c
  }
  return out
}

/** Removes `.` and `..` segments from a path, per RFC 3986 section 5.2.4. */
function removeDotSegments(path) {
  const output = []
  let input = path
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = /^(\/?[^/]*)(\/.*)?$/.exec(input)
      output.push(match[1])
      input = match[2] || ''
    }
  }
  return output.join('')
}

function serialize(scheme, authority, path, query, fragment) {
  let out = ''
  if (scheme !== undefined) out += scheme + ':'
  if (authority !== undefined) out += '//' + authority
  out += path
  if (query !== undefined) out += '?' + query
  if (fragment !== undefined) out += '#' + fragment
  return out
}

/**
 * Normalizes an already-split set of components and serializes the result.
 * Percent-encoding errors are reported in the order path, userinfo, host,
 * query, fragment.
 */
function normalizeComponents({ scheme, authority, path, query, fragment }, lineNum) {
  const normScheme = scheme !== undefined ? asciiLowercase(scheme) : undefined
  const authParsed = authority !== undefined ? parseAuthority(authority) : undefined

  const normPath = normalizePercent(path, 'path', lineNum)
  let normUserinfo, normHost, normPort
  if (authParsed !== undefined) {
    normUserinfo = normalizePercent(authParsed.userinfo, 'userinfo', lineNum)
    normHost = normalizePercent(authParsed.host, 'host', lineNum)
    normPort = authParsed.port
  }
  const normQuery = normalizePercent(query, 'query', lineNum)
  const normFragment = normalizePercent(fragment, 'fragment', lineNum)

  if (normHost !== undefined) normHost = asciiLowercase(normHost)

  if (normPort !== undefined) {
    const def = normScheme !== undefined ? DEFAULT_PORTS[normScheme] : undefined
    if (normPort === '' || normPort === def) normPort = undefined
  }

  let finalPath = removeDotSegments(normPath)
  if (authParsed !== undefined && finalPath === '') finalPath = '/'

  let authorityOut
  if (authParsed !== undefined) {
    authorityOut = (normUserinfo !== undefined ? normUserinfo + '@' : '') + normHost + (normPort !== undefined ? ':' + normPort : '')
  }

  return serialize(normScheme, authorityOut, finalPath, normQuery, normFragment)
}

/** Normalizes one URI reference and returns the output line. */
export function normalizeReference(text, lineNum) {
  return normalizeComponents(parseReference(text), lineNum)
}

/** Merges a relative reference path onto a base, per RFC 3986 section 5.2.3. */
function merge(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  return idx === -1 ? refPath : base.path.slice(0, idx + 1) + refPath
}

/** Resolves `refStr` against `baseStr` and returns the normalized output line. */
export function resolveReference(baseStr, refStr, lineNum) {
  const base = parseReference(baseStr)
  if (base.scheme === undefined) {
    throw new UriError(`line ${lineNum}: the base has no scheme`)
  }
  const ref = parseReference(refStr)

  let target
