/**
 * Uppercases the hex digits of every `%XX` in `component` and decodes the
 * ones that spell an unreserved character. Throws when a `%` is not
 * followed by two hex digits.
 */
function normalizePercent(component, label, lineNum) {
  if (component === undefined) return undefined
  let out = ''
  for (let i = 0; i < component.length; i++) {
    const c = component[i]
    if (c !== '%') {
      out += c
      continue
    }
    const d1 = component[i + 1]
    const d2 = component[i + 2]
    if (d1 === undefined || d2 === undefined || !isHexDigit(d1) || !isHexDigit(d2)) {
      throw new UriError(`line ${lineNum}: the ${label} has a truncated percent-encoding`)
    }
    const hex = (d1 + d2).toUpperCase()
    const ch = String.fromCharCode(parseInt(hex, 16))
    out += isUnreserved(ch) ? ch : '%' + hex
