/** Removes `.` and `..` segments from a path, per RFC 3986 section 5.2.4. */
function removeDotSegments(path) {
  const output = []
  let input = path
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output.pop()
    } else if (input === '/..') {
      input = '/'
      output.pop()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const match = /^(\/?[^/]*)(\/.*)?$/.exec(input)
      output.push(match[1])
