  if (fragment !== undefined) out += '#' + fragment
  return out
}

/**
 * Normalizes an already-split set of components and serializes the result.
 * Percent-encoding errors are reported in the order path, userinfo, host,
 * query, fragment.
 */
function normalizeComponents({ scheme, authority, path, query, fragment }, lineNum) {
  const normScheme = scheme !== undefined ? asciiLowercase(scheme) : undefined
  const authParsed = authority !== undefined ? parseAuthority(authority) : undefined

  const normPath = normalizePercent(path, 'path', lineNum)
  let normUserinfo, normHost, normPort
  if (authParsed !== undefined) {
    normUserinfo = normalizePercent(authParsed.userinfo, 'userinfo', lineNum)
    normHost = normalizePercent(authParsed.host, 'host', lineNum)
    normPort = authParsed.port
  }
  const normQuery = normalizePercent(query, 'query', lineNum)
