  let target
  if (ref.scheme !== undefined) {
    target = { scheme: ref.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  } else if (ref.authority !== undefined) {
    target = { scheme: base.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  } else if (ref.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
      fragment: ref.fragment,
    }
  } else {
    const path = ref.path.startsWith('/') ? ref.path : merge(base, ref.path)
    target = { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
  }

  return normalizeComponents(target, lineNum)
}
