{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-u8cHZP/src/format.js","content":"/**
 * Renders the full output of the `rounds` mode: one `round K: ...` line
 * per round counted, an `eliminated <name>` line after any round that
 * eliminated someone, and a trailing `winner <name>` or `no winner` line.
 */
export function formatRounds({ rounds, winner }) {
  const lines = []
  rounds.forEach((round, index) => {
    lines.push(`round ${index + 1}: ${formatVotes(round.votes)} exhausted=${round.exhausted}`)
    if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
  })
  lines.push(winner !== null ? `winner ${winner}` : 'no winner')
  return lines.join('\n') + '\n'
}

/** Renders the full output of the `tally` mode: the round count and the outcome. */
export function formatTally({ rounds, winner }) {
  const lines = [`rounds ${rounds.length}`, winner !== null ? `winner ${winner}` : 'no winner']
  return lines.join('\n') + '\n'
}

function formatVotes(votes) {
  const entries = [...votes.entries()]
  entries.sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesA > votesB ? -1 : 1
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  return entries.map(([name, count]) => `${name}=${count}`).join(' ')
}
"}

