{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-uPf3O8/src/parse.js","content":"/**
 * Parsing of the election description read from standard input into a
 * candidate list and a set of ballots, per the format defined in the task
 * specification.
 */

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/** Thrown for any malformed input; `line` is null for whole-input errors. */
export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

/**
 * Parses `input` and returns `{ candidates, ballots }`, where `candidates`
 * is the declared names in declaration order and `ballots` is a list of
 * `{ count, names }` in the order they appeared.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidateSet = null
  let candidateOrder = []
  const ballots = []
  let sawBallot = false

  for (let index = 0; index < lines.length; index += 1) {
    const lineNo = index + 1
    const trimmed = lines[index].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidateSet !== null || sawBallot) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 2) {
        throw new ParseError('expected candidates <name>...', lineNo)
      }
      const names = tokens.slice(1)
      const set = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNo)
        }
        if (set.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNo)
        }
        set.add(name)
      }
      candidateSet = set
      candidateOrder = names
    } else if (word === 'ballot') {
      if (candidateSet === null) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNo)
      }
      sawBallot = true
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNo)
      }
      if (!COUNT_PATTERN.test(tokens[1])) {
        throw new ParseError('count must be a positive integer', lineNo)
      }
      const count = Number(tokens[1])
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${word}`, lineNo)
    }
  }

  if (candidateSet === null) {
    throw new ParseError('no candidates', null)
  }

  return { candidates: candidateOrder, ballots }
}
"}

