/**
 * Formats round `roundNumber`'s line: candidates by descending vote count,
 * then ascending name, followed by the exhausted-ballot total.
 */
export function formatRoundLine(roundNumber, counts, exhausted) {
  const entries = [...counts.entries()].sort(([nameA, votesA], [nameB, votesB]) => {
    if (votesA !== votesB) return votesB - votesA
    return nameA < nameB ? -1 : 1
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  return `round ${roundNumber}: ${parts.join(' ')} exhausted=${exhausted}`
}
"}

