 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 *
 * Every URI (reference) is represented as a plain object with the fields
 * below. Presence and emptiness are distinct for the authority, query and
 * fragment components, so each carries its own `*Present` flag alongside the
 * string value (which is `undefined` when the component is absent).
 *
 *   { schemePresent, scheme,
 *     authorityPresent, authority,
 *     path,
 *     queryPresent, query,
 *     fragmentPresent, fragment }
 */

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {
  constructor(detail) {
    super(detail)
    this.detail = detail
  }
}

/** Split a URI reference into its five generic-syntax components. */
export function parseUriReference(s) {
  let rest = s

  let schemePresent = false
  let scheme
  const colonIdx = rest.indexOf(':')
  if (colonIdx !== -1 && !/[/?#]/.test(rest.slice(0, colonIdx))) {
    schemePresent = true
    scheme = rest.slice(0, colonIdx)
    rest = rest.slice(colonIdx + 1)
  }

  let authorityPresent = false
  let authority
  if (rest.startsWith('//')) {
    authorityPresent = true
    rest = rest.slice(2)
    let end = rest.length
    for (const ch of ['/', '?', '#']) {
      const idx = rest.indexOf(ch)
      if (idx !== -1 && idx < end) end = idx
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let end = rest.length
  for (const ch of ['?', '#']) {
    const idx = rest.indexOf(ch)
    if (idx !== -1 && idx < end) end = idx
  }
  const path = rest.slice(0, end)
  rest = rest.slice(end)

  let queryPresent = false
  let query
  if (rest.startsWith('?')) {
    queryPresent = true
    rest = rest.slice(1)
    const hashIdx = rest.indexOf('#')
    if (hashIdx === -1) {
      query = rest
      rest = ''
    } else {
      query = rest.slice(0, hashIdx)
      rest = rest.slice(hashIdx)
    }
  }

  let fragmentPresent = false
  let fragment
  if (rest.startsWith('#')) {
    fragmentPresent = true
    fragment = rest.slice(1)
  }

  return { schemePresent, scheme, authorityPresent, authority, path, queryPresent, query, fragmentPresent, fragment }
}

/** Split an authority into userinfo, host and port, per the task's rules. */
function parseAuthority(authority) {
  const atIdx = authority.lastIndexOf('@')
  let userinfoPresent = false
  let userinfo
  let rest = authority
  if (atIdx !== -1) {
    userinfoPresent = true
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = rest.indexOf(':', searchFrom)

  let host
  let portPresent = false
  let port
  if (colonIdx === -1) {
    host = rest
  } else {
    host = rest.slice(0, colonIdx)
    portPresent = true
    port = rest.slice(colonIdx + 1)
  }

  return { userinfoPresent, userinfo, host, portPresent, port }
}

/** Serialize a URI (reference) back into text. */
export function serialize(u) {
  let out = ''
  if (u.schemePresent) out += u.scheme + ':'
  if (u.authorityPresent) out += '//' + u.authority
  out += u.path
  if (u.queryPresent) out += '?' + u.query
  if (u.fragmentPresent) out += '#' + u.fragment
  return out
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) + 32))
}

