const UNRESERVED = /^[A-Za-z0-9\-._~]$/

/**
 * Normalize percent-encoded triplets in one component: uppercase the hex
 * digits, then decode triplets that spell an unreserved character.
 */
function normalizePercents(s, componentName) {
  let out = ''
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '%') {
      const digits = s.slice(i + 1, i + 3)
      if (digits.length < 2 || !HEX_PAIR.test(digits)) {
        throw new UriError(`the ${componentName} has a truncated percent-encoding`)
      }
      const upper = digits.toUpperCase()
      const ch = String.fromCharCode(parseInt(upper, 16))
      out += UNRESERVED.test(ch) ? ch : '%' + upper
      i += 2
    } else {
      out += s[i]
    }
  }
  return out
}

/** Remove `.` and `..` segments from a path per RFC 3986 section 5.2.4. */
function removeDotSegments(input) {
  let output = ''
  while (input.length) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '/..') {
      input = '/'
      const idx = output.lastIndexOf('/')
      output = idx === -1 ? '' : output.slice(0, idx)
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const idx = input[0] === '/' ? input.indexOf('/', 1) : input.indexOf('/')
      if (idx === -1) {
        output += input
        input = ''
      } else {
        output += input.slice(0, idx)
        input = input.slice(idx)
      }
    }
  }
  return output
}

