 * Normalize an already-parsed URI (reference). Percent-encoding validity is
 * checked in the fixed order path, userinfo, host, query, fragment, so the
 * first invalid component in that order determines the error.
 */
export function normalizeParsed(u) {
  const authParts = u.authorityPresent ? parseAuthority(u.authority) : null

  const path = normalizePercents(u.path, 'path')
  const userinfo = authParts && authParts.userinfoPresent ? normalizePercents(authParts.userinfo, 'userinfo') : undefined
  const host = authParts ? normalizePercents(authParts.host, 'host') : undefined
  const query = u.queryPresent ? normalizePercents(u.query, 'query') : undefined
  const fragment = u.fragmentPresent ? normalizePercents(u.fragment, 'fragment') : undefined

  const scheme = u.schemePresent ? asciiLower(u.scheme) : undefined
  const loweredHost = authParts ? asciiLower(host) : undefined

  let portPresent = authParts ? authParts.portPresent : false
  const port = authParts ? authParts.port : undefined
  if (portPresent) {
    if (port === '') {
      portPresent = false
    } else if (scheme !== undefined && DEFAULT_PORTS[scheme] === port) {
      portPresent = false
    }
  }

  let path2 = removeDotSegments(path)
  if (u.authorityPresent && path2 === '') path2 = '/'

  let authority
  if (u.authorityPresent) {
    let a = ''
    if (authParts.userinfoPresent) a += userinfo + '@'
    a += loweredHost
    if (portPresent) a += ':' + port
    authority = a
  }

  return {
    schemePresent: u.schemePresent,
    scheme,
    authorityPresent: u.authorityPresent,
    authority,
    path: path2,
    queryPresent: u.queryPresent,
    query,
    fragmentPresent: u.fragmentPresent,
    fragment,
  }
}

function mergePaths(base, refPath) {
  if (base.authorityPresent && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/** Resolve a reference against a base per RFC 3986 section 5.2.2 (strict). */
export function resolveComponents(base, ref) {
  const target = {}

  if (ref.schemePresent) {
    target.schemePresent = true
    target.scheme = ref.scheme
    target.authorityPresent = ref.authorityPresent
    target.authority = ref.authority
    target.path = ref.path
    target.queryPresent = ref.queryPresent
    target.query = ref.query
  } else {
    target.schemePresent = true
    target.scheme = base.scheme
    if (ref.authorityPresent) {
      target.authorityPresent = true
      target.authority = ref.authority
      target.path = ref.path
      target.queryPresent = ref.queryPresent
      target.query = ref.query
    } else {
      target.authorityPresent = base.authorityPresent
      target.authority = base.authority
      if (ref.path === '') {
        target.path = base.path
        if (ref.queryPresent) {
          target.queryPresent = true
          target.query = ref.query
        } else {
          target.queryPresent = base.queryPresent
          target.query = base.query
        }
      } else {
        target.path = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
        target.queryPresent = ref.queryPresent
        target.query = ref.query
      }
    }
  }

  target.fragmentPresent = ref.fragmentPresent
  target.fragment = ref.fragment

  return target
}
