{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-yoBKzS/src/diff.js","content":"/**
 * Longest-common-subsequence diffing between a side document and the base it
 * derives from, using exact line equality and the earliest-match tie-break
 * described in the task: when the two candidate subsequences are equally
 * long, advance the side whose remaining subsequence is at least as long as
 * the other's, preferring to advance the base on a tie.
 */

/**
 * Find the sequence of (baseIndex, sideIndex) pairs of matched, identical
 * lines between `base` and `side`, following the longest-common-subsequence
 * with earliest-match tie-breaking.
 */
function lcsMatches(base, side) {
  const n = base.length
  const m = side.length
  // dp[i][j] holds the LCS length of base[i:] and side[j:], stored as a flat
  // (n+1) x (m+1) array of suffix lengths so the forward walk below can
  // compare "remaining subsequence" lengths without recomputation.
  const width = m + 1
  const dp = new Int32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      const here = i * width + j
      if (base[i] === side[j]) {
        dp[here] = dp[(i + 1) * width + (j + 1)] + 1
      } else {
        const advanceBase = dp[(i + 1) * width + j]
        const advanceSide = dp[i * width + (j + 1)]
        dp[here] = advanceBase >= advanceSide ? advanceBase : advanceSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
    } else {
      const advanceBase = dp[(i + 1) * width + j]
      const advanceSide = dp[i * width + (j + 1)]
      if (advanceBase >= advanceSide) {
        i++
      } else {
        j++
      }
    }
  }
  return matches
}

/**
 * Turn the stretches between matches into changes: runs of base lines
 * replaced by runs of the side's lines. An insertion replaces zero base
 * lines and a deletion inserts zero lines.
 */
function diffAgainstBase(base, side, sideName) {
  const matches = lcsMatches(base, side)
  const changes = []
  let prevBase = 0
  let prevSide = 0
  for (const [mi, mj] of matches) {
    if (mi > prevBase || mj > prevSide) {
      changes.push({
        side: sideName,
        baseStart: prevBase,
        baseEnd: mi,
        lines: side.slice(prevSide, mj),
      })
    }
    prevBase = mi + 1
    prevSide = mj + 1
  }
  if (prevBase < base.length || prevSide < side.length) {
    changes.push({
      side: sideName,
      baseStart: prevBase,
      baseEnd: base.length,
      lines: side.slice(prevSide, side.length),
    })
  }
  return changes
}

module.exports = { diffAgainstBase }
"}

