{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-yoBKzS/src/merge.js","content":"/**
 * Three-way merge of `mine` and `theirs` against their common `base`,
 * expressed as a sequence of blocks covering the whole base document in
 * order: stable stretches the merge leaves unchanged, and regions resolved
 * from the changes each side made against the base.
 */

import { diffAgainstBase } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Group changes into regions: consecutive changes are absorbed into the same
 * region while a change starts at or before the region's current end.
 */
function buildRegions(changes) {
  const regions = []
  let i = 0
  while (i < changes.length) {
    let start = changes[i].baseStart
    let end = changes[i].baseEnd
    const group = [changes[i]]
    i++
    while (i < changes.length && changes[i].baseStart <= end) {
      group.push(changes[i])
      if (changes[i].baseEnd > end) end = changes[i].baseEnd
      i++
    }
    regions.push({ baseStart: start, baseEnd: end, changes: group })
  }
  return regions
}

/**
 * Reconstruct one side's lines across a region from that side's own changes
 * touching it, filling the stretches between and around those changes with
 * the base lines the side left untouched there.
 */
function fillSide(sideChanges, base, regionStart, regionEnd) {
  if (sideChanges.length === 0) return base.slice(regionStart, regionEnd)
  const result = base.slice(regionStart, sideChanges[0].baseStart)
  let cursor = sideChanges[0].baseStart
  for (const change of sideChanges) {
    result.push(...base.slice(cursor, change.baseStart))
    result.push(...change.lines)
    cursor = change.baseEnd
  }
  result.push(...base.slice(cursor, regionEnd))
  return result
}

/**
 * Resolve a region to one side's lines, "both" when the sides made the same
 * change, or a conflict carrying all three renderings.
 */
function resolveRegion(region, base) {
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  const mineChanges = region.changes.filter(c => c.side === 'mine')
  const theirsChanges = region.changes.filter(c => c.side === 'theirs')
  const mineLines = fillSide(mineChanges, base, region.baseStart, region.baseEnd)
  const theirsLines = fillSide(theirsChanges, base, region.baseStart, region.baseEnd)

  let type
  if (arraysEqual(mineLines, theirsLines)) {
    type = mineChanges.length > 0 && theirsChanges.length > 0 ? 'both' : mineChanges.length > 0 ? 'mine' : 'theirs'
  } else if (arraysEqual(mineLines, baseLines)) {
    type = 'theirs'
  } else if (arraysEqual(theirsLines, baseLines)) {
    type = 'mine'
  } else {
    type = 'conflict'
  }

  const lines = type === 'mine' ? mineLines : type === 'theirs' ? theirsLines : type === 'both' ? mineLines : undefined
  return { type, lines, baseLines, mineLines, theirsLines }
}

/**
 * Compute the ordered list of blocks covering the whole base document: each
 * is `{ type: 'stable', lines }` or the result of `resolveRegion` with
 * `type` one of `mine`, `theirs`, `both`, `conflict`.
 */
function mergeBlocks(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine, 'mine')
  const theirsChanges = diffAgainstBase(base, theirs, 'theirs')
  const changes = [...mineChanges, ...theirsChanges].sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })
  const regions = buildRegions(changes)

  const blocks = []
  let cursor = 0
  for (const region of regions) {
    if (region.baseStart > cursor) {
      blocks.push({ type: 'stable', lines: base.slice(cursor, region.baseStart) })
    }
    blocks.push(resolveRegion(region, base))
    cursor = region.baseEnd
  }
  if (cursor < base.length) {
    blocks.push({ type: 'stable', lines: base.slice(cursor, base.length) })
  }
  return blocks
}

export { mergeBlocks }
"}

