{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-yoBKzS/src/format.js","content":"/**
 * Render merge blocks (see merge.js) into the output text for each of the
 * three CLI modes, reporting whether a conflict was written.
 */

function renderMerge(blocks, { includeBase }) {
  const out = []
  let hadConflict = false
  for (const block of blocks) {
    if (block.type === 'conflict') {
      hadConflict = true
      out.push('<<<<<<< mine', ...block.mineLines)
      if (includeBase) out.push('||||||| base', ...block.baseLines)
      out.push('=======', ...block.theirsLines, '>>>>>>> theirs')
    } else {
      out.push(...block.lines)
    }
  }
  const text = out.length === 0 ? '' : out.join('\n') + '\n'
  return { text, hadConflict }
}

function renderRegions(blocks) {
  const out = []
  let hadConflict = false
  for (const block of blocks) {
    if (block.type === 'conflict') {
      hadConflict = true
      out.push(`conflict mine=${block.mineLines.length} base=${block.baseLines.length} theirs=${block.theirsLines.length}`)
    } else {
      out.push(`${block.type} ${block.lines.length}`)
    }
  }
  const text = out.length === 0 ? '' : out.join('\n') + '\n'
  return { text, hadConflict }
}

export { renderMerge, renderRegions }
